local function tokens(s)
local out = {}
for t in string.gmatch(s or "", "[^%s,]+") do table.insert(out, t) end
return out
end
local function matchAny(s, words)
for _, w in ipairs(words) do
if string.find(s, w, 1, true) then return true end
end
return false
end
