function Shot.autoSave()
local parts = {}
for key, a in pairs(Shot.auto) do parts[#parts + 1] = string.format("%s:%s=%.4f", a.mode == "peak" and (a.locked and "l" or "p") or (a.locked and "L" or "P"), key, a.hold) end
