function UI.corner(o, factor)
local c = new("UICorner", { Parent = o })
if factor == "pill" then
c.CornerRadius = UDim.new(1, 0)
else
table.insert(UI.corners, { c, factor or 1 })
c.CornerRadius = UDim.new(0, math.floor(S.Corner * (factor or 1)))
end
return c
end
function UI.card(f)
