local bar = new("Frame", { Position = UDim2.new(0, 34, 0, 34), Size = UDim2.new(1, -68, 0, 8), Parent = r })
UI.elem(bar)
UI.corner(bar, "pill")
local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = WHITE, Parent = bar })
