fpsStat.Text = string.format("%d", math.floor(JH.FPS + 0.5))
pingStat.Text = string.format("%d ms", math.floor(Ping.raw * 1000 + 0.5))
stableStat.Text = Ping.stable and string.format("%d ms", math.floor(Ping.stable * 1000 + 0.5)) or "-"
