do
local OWNER, REPO, BRANCH = "jaydendagoat2", "jayhubv1", "claude/j"
local function http(url) return game:HttpGet(url) end
local function latestSha()
local branch = string.gsub(BRANCH, "/", "%%2F")
local ok, body = pcall(http, "https://api.github.com/repos/" .. OWNER .. "/" .. REPO .. "/commits/" .. branch)
if not ok or type(body) ~= "string" then return nil end
return string.match(body, '"sha"%s*:%s*"(%x+)"')
end
local function fetchNewest()
local sha = latestSha()
local url = sha and ("https://raw.githubusercontent.com/" .. OWNER .. "/" .. REPO .. "/" .. sha .. "/J.lua")
or ("https://raw.githubusercontent.com/" .. OWNER .. "/" .. REPO .. "/" .. BRANCH .. "/J.lua?v=" .. tostring(os.time()))
local ok, src = pcall(http, url)
if not ok or type(src) ~= "string" or #src < 10000 then return nil end
local ver = string.match(src, "JHUB_VERSION:%s*(v[%d%.]+)") or string.match(src, 'local VERSION = "(v[%d%.]+)')
return src, ver
end
local mine = string.match(tostring(VERSION), "^(v[%d%.]+)") or tostring(VERSION)
local function numver(v)
local maj, minr = string.match(tostring(v), "v?(%d+)%.?(%d*)")
return (tonumber(maj) or 0) * 1000 + (tonumber(minr) or 0)
end
local busy = false
local newestLbl
local function doUpdate(silent)
if busy then return end
busy = true
if newestLbl then newestLbl.Text = "downloading..." end
local src, ver = fetchNewest()
if not src then
if newestLbl then newestLbl.Text = "could not reach GitHub" end
busy = false
return
end
if newestLbl then newestLbl.Text = ver or "could not read version" end
if not ver then
if not silent then notify("Update", "Could not read a version from the download, not updating.", 4) end
busy = false
return
end
if numver(ver) <= numver(mine) then
if not silent then notify("Update", "You already have the newest version (" .. mine .. ")", 4) end
busy = false
return
end
local fn = loadstring(src)
if not fn then
if not silent then notify("Update", "The download could not be read", 4) end
busy = false
return
end
notify("Update", "A newer version (" .. tostring(ver) .. ") was found, updating now...", 4)
if S.AutoExec then
pcall(function()
local code = "(getgenv and getgenv() or _G).JHUB_AUTOEXEC = true\n" .. src
for _, f in ipairs(Net.AUTOEXEC_FOLDERS) do
pcall(function()
if type(isfolder) == "function" and isfolder(f) then writefile(f .. "/" .. Net.AUTOEXEC_FILE, code) end
end)
end
pcall(FS.write, FS.root .. "/" .. Net.AUTOEXEC_FILE, src)
local q = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
if type(q) == "function" then pcall(q, code) end
end)
end
pcall(JH.Unload)
task.defer(fn)
end
task.spawn(function()
task.wait(6)
if S.AutoUpdate ~= false and JH.Running then pcall(doUpdate, true) end
end)
local mainPage
for _, p in ipairs(UI.pages) do
if p.name == "Main" then mainPage = p end
end
if mainPage then
local c = UI.Card(mainPage, "Updates")
local cur = UI.Stat(c, "This version")
cur.Text = mine
newestLbl = UI.Stat(c, "Newest version")
newestLbl.Text = "tap Check"
UI.Toggle(c, "Check for updates automatically on load", "AutoUpdate")
UI.Buttons(c, {
{ "Check", function()
if busy then return end
busy = true
newestLbl.Text = "checking..."
local src, ver = fetchNewest()
newestLbl.Text = ver or "could not reach GitHub"
busy = false
end },
{ "Update now", function() doUpdate(false) end },
})
UI.Note(c, "Loads the newest version from GitHub and restarts JHub. Your settings stay.")
end
end
do
