local IMG = { "Image", "ImageRectOffset", "ImageRectSize", "ScaleType", "SliceCenter", "Size", "Position", "AnchorPoint", "Rotation", "ZIndex" }
local GUIP = { "Size", "StudsOffset", "ExtentsOffset", "LightInfluence", "AlwaysOnTop" }
local snaps = {}      -- gui -> { props, children = { child -> props }, added = {}, hidden = {} }
local swapped = {}    -- gui -> the meter name it currently looks like
local yRot = {}       -- gui -> rotation to keep on its fill gradient
local conns = {}
local function readProps(o, list)
local t = {}
for _, p in ipairs(list) do
local ok, v = pcall(function() return o[p] end)
if ok then t[p] = v end
end
return t
end
local function writeProps(o, t)
for p, v in pairs(t) do pcall(function() o[p] = v end) end
end
local function guiOf(ch, name)
local r = ch:FindFirstChild("HumanoidRootPart")
local g = r and r:FindFirstChild(name .. "Meter")
if g then return g end
local h = ch:FindFirstChild("Head")
return h and h:FindFirstChild(name .. "Meter")
end
local function equipped(ch)
local ok, mod = pcall(function() return require(LP.PlayerScripts.Aero.Controllers.Meter) end)
local pk = ok and type(mod) == "table" and mod.ActivePackets and mod.ActivePackets[ch]
if pk and pk.meterType then S.GameMeter = pk.meterType end
return S.GameMeter
end
local function snapshot(g)
if snaps[g] then return end
local s = { props = readProps(g, GUIP), children = {}, added = {}, hidden = {}, grads = {} }
for _, c in ipairs(g:GetChildren()) do
if c:IsA("ImageLabel") then
s.children[c] = readProps(c, IMG)
s.children[c].ImageColor3 = c.ImageColor3
elseif c:IsA("UIGradient") then
s.grads[c] = { Color = c.Color }
end
end
snaps[g] = s
end
local function restore(g)
local s = snaps[g]
if not s then return end
writeProps(g, s.props)
for c, p in pairs(s.children) do
if c.Parent then writeProps(c, p) end
end
for c, p in pairs(s.grads) do
if c.Parent then writeProps(c, p) end
end
for _, c in ipairs(s.added) do pcall(function() c:Destroy() end) end
for c, v in pairs(s.hidden) do if c.Parent then c.Visible = v end end
g:SetAttribute("JHSX", nil)
g:SetAttribute("JHSY", nil)
swapped[g] = nil
yRot[g] = nil
end
local function becomeLike(g, y)
snapshot(g)
writeProps(g, readProps(y, GUIP))
local s = snaps[g]
for _, yc in ipairs(y:GetChildren()) do
if yc:IsA("ImageLabel") then
local gc = g:FindFirstChild(yc.Name)
if not gc then
gc = yc:Clone()
gc.ImageTransparency = 1
gc.Parent = g
s.added[#s.added + 1] = gc
else
writeProps(gc, readProps(yc, IMG))
gc.ImageColor3 = yc.ImageColor3
end
elseif yc:IsA("UIGradient") and g:FindFirstChild(yc.Name) then
g[yc.Name].Color = yc.Color
end
end
local gradY = y:FindFirstChild("FillGradient", true)
local gradG = g:FindFirstChild("FillGradient", true)
for _, gc in ipairs(g:GetChildren()) do
if gc:IsA("ImageLabel") and not y:FindFirstChild(gc.Name) and not table.find(s.added, gc) then
s.hidden[gc] = gc.Visible
gc.Visible = false
end
end
if gradG and gradY then
yRot[g] = gradY.Rotation
gradG.Rotation = gradY.Rotation
conns[#conns + 1] = gradG:GetPropertyChangedSignal("Rotation"):Connect(function()
if yRot[g] and gradG.Rotation ~= yRot[g] then gradG.Rotation = yRot[g] end
end)
end
g:SetAttribute("JHSX", nil)
g:SetAttribute("JHSY", nil)
swapped[g] = y.Name
end
local function look(g)
local s = snaps[g]
local on = S.CustomMeterOn == true
if not s then snapshot(g) s = snaps[g] end
local base = swapped[g] and g:GetAttribute("JHBase") or nil
if not g:GetAttribute("JHSX") then
g:SetAttribute("JHSX", g.Size.X.Scale)
g:SetAttribute("JHSY", g.Size.Y.Scale)
end
local k = on and (S.MeterSize or 1) or 1
local bx, by = g:GetAttribute("JHSX"), g:GetAttribute("JHSY")
if not bx or bx <= 0 then bx, by = g.Size.X.Scale, g.Size.Y.Scale end
local want = UDim2.new(bx * k, g.Size.X.Offset, by * k, g.Size.Y.Offset)
if g.Size ~= want then g.Size = want end
local fill = g:FindFirstChild("Meter_Fill")
if fill then
local col
if on and S.MeterColorOn == true then
col = Color3.fromRGB(S.MeterR or 255, S.MeterG or 255, S.MeterB or 255)
else
col = (swapped[g] and fill.ImageColor3) or (s.children[fill] and s.children[fill].ImageColor3) or fill.ImageColor3
end
if fill.ImageColor3 ~= col and (on and S.MeterColorOn == true or not swapped[g]) then fill.ImageColor3 = col end
end
end
local function refresh()
local ch = char()
if not ch then return end
local X = equipped(ch)
if not X then return end
local gx = guiOf(ch, X)
if not gx then return end
local want = S.CustomMeterOn == true and S.CustomMeter or nil
if want and want ~= X then
if swapped[gx] ~= want then
if swapped[gx] then restore(gx) end
local y = guiOf(ch, want)
if y then becomeLike(gx, y) end
end
elseif swapped[gx] or snaps[gx] then
if swapped[gx] then restore(gx) end
end
if S.CustomMeterOn == true or snaps[gx] then pcall(look, gx) end
end
task.spawn(function()
while JH.Running do
pcall(refresh)
task.wait(0.25)
end
end)
local prevUnload = JH.Unload
function JH.Unload()
S.CustomMeterOn = false
pcall(function()
local ch = char()
local X = ch and S.GameMeter
local gx = X and guiOf(ch, X)
if gx then
restore(gx)
local bx, by = gx:GetAttribute("JHSX"), gx:GetAttribute("JHSY")
if bx then gx.Size = UDim2.new(bx, gx.Size.X.Offset, by, gx.Size.Y.Offset) end
end
end)
for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
if prevUnload then prevUnload() end
end
end
end
