local HELPER_FLAGS = {}
local function helperFlag(f) HELPER_FLAGS[#HELPER_FLAGS + 1] = f end
local function syncHelpers()
local need = false
for _, f in ipairs(HELPER_FLAGS) do
if S[f] == true then need = true break end
end
local ok = JH.OK
if not ok then return end
if need and not ok.running then pcall(ok.start) end
if not need and ok.running then pcall(ok.stop) end
end

local Tabs = {}
local function newTab(name, glyph)
local p = find(name) or UI.Page(name, glyph)
p.order = 0
local lay = p.frame:FindFirstChildOfClass("UIListLayout")
if lay then
lay.FillDirection = Enum.FillDirection.Horizontal
lay.Wraps = true
lay.Padding = UDim.new(0, 8)
lay.HorizontalAlignment = Enum.HorizontalAlignment.Left
lay.VerticalAlignment = Enum.VerticalAlignment.Top
end
local t = { page = p, flags = {}, defaults = {}, name = name, after = nil }
Tabs[#Tabs + 1] = t
return t
end
local function card(t, title, full)
local c = UI.Card(t.page, title)
for _, ch in ipairs(c.frame:GetChildren()) do
if ch:IsA("UIStroke") then ch:Destroy() end
end
local pad = c.frame:FindFirstChildOfClass("UIPadding")
if pad then
pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 4), UDim.new(0, 4)
pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 6), UDim.new(0, 6)
end
local ll = c.frame:FindFirstChildOfClass("UIListLayout")
if ll then ll.Padding = UDim.new(0, 2) end
c.frame.Size = full and UDim2.new(1, -4, 0, 0) or UDim2.new(0.5, -6, 0, 0)
c.tab = t
t.page.order = (t.page.order or 0) + 10
c.frame.LayoutOrder = t.page.order
return c
end
local function track(c, flag, default)
local t = c.tab
if type(flag) == "string" and not t.flags[flag] then
t.flags[flag] = true
t.flags[#t.flags + 1] = flag
if default ~= nil then t.defaults[flag] = default end
end
end
local function tog(c, text, flag, cb, default)
track(c, flag, default)
return UI.Toggle(c, text, flag, cb)
end
local function sld(c, text, flag, mn, mx, step, dec, suffix, cb, default)
track(c, flag, default)
return UI.Slider(c, text, flag, mn, mx, step, dec, suffix, cb)
end
local function drop(c, text, flag, options, cb, default)
track(c, flag, default)
return UI.Dropdown(c, text, flag, options, cb)
end
local function note(c, text) return UI.Note(c, text) end
local function seed(flag, v) if S[flag] == nil then S[flag] = v end end
local function resetCard(t)
local c = card(t, "Reset", true)
c.frame.LayoutOrder = 999
UI.Button(c, "Reset this tab", function()
for _, f in ipairs(t.flags) do
local d = t.defaults[f]
if d == nil then d = DEFAULTS[f] end
S[f] = d
pcall(UI.set, f, d, false)
end
if t.after then pcall(t.after) end
syncHelpers()
pcall(UI.refreshAll)
saveSoon()
notify("JHub", t.name .. " is back to default", 2)
end)
return c
end

