do
local RED, ORANGE, GREEN = Color3.fromRGB(235, 60, 60), Color3.fromRGB(255, 150, 40), Color3.fromRGB(70, 220, 110)
local items = {}
local folder
local function kill(c)
local it = items[c]
if not it then return end
for _, o in pairs(it) do pcall(function() o:Destroy() end) end
items[c] = nil
end
local function killAll()
for c in pairs(items) do kill(c) end
if folder then pcall(function() folder:Destroy() end) folder = nil end
end
local function rootOf(c) return c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart end
local function sideOf(c) return c:GetAttribute("HomeTeam") end
local function shade(d)
if d <= 5 then return RED, "COVERED" elseif d <= 10 then return ORANGE, "CLOSE" end
return GREEN, "OPEN"
end
local function all()
local list = {}
local chars = workspace:FindFirstChild("Characters")
if chars then
for _, m in ipairs(chars:GetChildren()) do
if m:IsA("Model") and m.Name ~= "InvisCharacter" then
local r, h = rootOf(m), m:FindFirstChildOfClass("Humanoid")
if r and h and h.Health > 0 then list[#list + 1] = m end
end
end
end
return list
end
local function show(c, d, isMe)
local col, word = shade(d)
local it = items[c]
if not it then
it = {}
items[c] = it
folder = folder or Instance.new("Folder")
folder.Name = "JHContest"
if not folder.Parent then folder.Parent = workspace.CurrentCamera end
local r = rootOf(c)
local bb = Instance.new("BillboardGui")
bb.Size = UDim2.fromOffset(110, 34)
bb.StudsOffset = Vector3.new(0, 4.4, 0)
bb.AlwaysOnTop = true
bb.Adornee = r
bb.Parent = folder
local tl = Instance.new("TextLabel")
tl.Size = UDim2.fromScale(1, 1)
tl.BackgroundTransparency = 1
tl.Font = Enum.Font.GothamBold
tl.TextSize = 16
tl.TextStrokeTransparency = 0.3
tl.Parent = bb
it.bb, it.tl = bb, tl
local hl = Instance.new("Highlight")
hl.FillTransparency = 0.65
hl.OutlineTransparency = 0.2
hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
hl.Adornee = c
hl.Parent = folder
it.hl = hl
local ring = Instance.new("Part")
ring.Shape = Enum.PartType.Cylinder
ring.Size = Vector3.new(0.15, 5, 5)
ring.Anchored, ring.CanCollide, ring.CanQuery, ring.CanTouch, ring.CastShadow = true, false, false, false, false
ring.Material = Enum.Material.Neon
ring.Transparency = 0.35
ring.Parent = folder
it.ring = ring
end
it.tl.Text = word .. " " .. math.floor(math.clamp((10 - d) / 10, 0, 1) * 100 + 0.5) .. "%"
it.tl.TextColor3 = col
it.bb.Enabled = S.ContestHead ~= false
it.hl.FillColor, it.hl.OutlineColor = col, col
it.hl.Enabled = S.ContestGlow ~= false
it.ring.Color = col
local r = rootOf(c)
if r and it.ring then
it.ring.Transparency = (S.ContestGround ~= false) and 0.35 or 1
it.ring.CFrame = CFrame.new(r.Position - Vector3.new(0, 2.9, 0)) * CFrame.Angles(0, 0, math.rad(90))
end
end
task.spawn(function()
while JH.Running do
if S.ContestOn == true then
pcall(function()
local list = all()
local me = char()
local mySide = me and sideOf(me)
local seen = {}
for _, c in ipairs(list) do
local isMe = (c == me)
local foe = (not isMe) and (mySide == nil or sideOf(c) ~= mySide)
if isMe or (foe and S.ContestFoes ~= false) then
local rc = rootOf(c)
local best = math.huge
for _, o in ipairs(list) do
if o ~= c then
local opp
if isMe then opp = (mySide == nil or sideOf(o) ~= mySide)
else opp = (sideOf(o) == mySide) or (o == me) or mySide == nil and false end
if opp then
local ro = rootOf(o)
local dd = (ro.Position - rc.Position).Magnitude
if dd < best then best = dd end
end
end
end
if best == math.huge then best = 30 end
show(c, best, isMe)
seen[c] = true
end
end
for c in pairs(items) do if not seen[c] or not c.Parent then kill(c) end end
end)
else
if next(items) then killAll() end
end
task.wait(0.15)
end
killAll()
end)
end
