local function JHubMain()

-- A re-run removes the previous copy of this menu and the older JHub menu first.
local genv = (getgenv and getgenv()) or shared or _G
local launchedByAuto = genv.JHUB_AUTOEXEC
genv.JHUB_AUTOEXEC = nil
if launchedByAuto then
	if not game:IsLoaded() then game.Loaded:Wait() end
	local okf, txt = pcall(function() return readfile("JHubGlass/settings.json") end)
	if okf and type(txt) == "string" and not string.find(txt, '"AutoExec":true', 1, true) then return end
end
for _, key in ipairs({ "JHubGlass", "JHubV1", "JayHubPB" }) do
	local old = genv[key]
	if type(old) == "table" and type(old.Unload) == "function" then
		pcall(old.Unload)
	end
	genv[key] = nil
end
-- this script used to be saved under the name JHubV1_Glass.lua - clean up any old copy still sitting under that
-- name on disk, every run, not just old-versus-new ones: an old copy under the old name would otherwise just keep
-- firing on its own forever, alongside this one, no matter what this one does, since it is a completely separate
-- file as far as the executor's own autoexec folder scanning is concerned
pcall(function()
	for _, folder in ipairs({ "autoexec", "Autoexec", "autoexecute", "Autoexecute" }) do
		pcall(function()
			local p = folder .. "/JHubV1_Glass.lua"
			if type(isfile) == "function" and isfile(p) and type(delfile) == "function" then delfile(p) end
		end)
	end
	pcall(function()
		local p = "JHubGlass/JHubV1_Glass.lua"
		if type(isfile) == "function" and isfile(p) and type(delfile) == "function" then delfile(p) end
	end)
end)
-- claim the slot immediately, with nothing that can yield between the unload loop above and this -
-- if the executor fires several copies of this script at once (e.g. more than one autoexec folder
-- holding a copy), each copy's unload-then-claim now runs as one uninterrupted stretch with no gap
-- for another copy to slip through, so only the very last one to reach this line survives: every
-- earlier one gets torn down here, before it ever gets as far as building its own menu. Previously
-- this claim happened after the LocalPlayer wait below, which yields and let every racing copy pass
-- the unload check seeing nothing to unload yet, then each one built its own full menu - the 7 (or
-- however many autoexec copies exist) stacked windows this caused.
local JH = { Connections = {}, Running = true, Logs = {}, Start = tick(), FPS = 60 }
genv.JHubGlass = JH
-- an early, minimal unload so a second load started before this one finishes can always stop
-- this one's background loops - the full Unload (destroys the menu, saves settings) replaces
-- this once it is defined further down
function JH.Unload()
	JH.Running = false
	for _, c in ipairs(JH.Connections) do pcall(function() c:Disconnect() end) end
end

