local TOUCH = Enum.UserInputType.Touch
local MMOVE = Enum.UserInputType.MouseMovement
local KEYBOARD = Enum.UserInputType.Keyboard
local IS_MOBILE = UIS.TouchEnabled and not UIS.KeyboardEnabled
local VERSION = "v2.52 (test)"

-- ACCESS CHECK: the script checks in with the backend before it does anything else. A copy of this file pulled
-- off disk or cracked open by a deobfuscator is still just an inert shell without the server saying yes - this
-- runs before any menu, feature or setting exists, so there is nothing to recover a "full" working copy from.
do
	local AUTH_URL = "https://jayhubv1-default-rtdb.firebaseio.com/control.json"
	local allowed, reason = true, nil
	pcall(function()
		local fn = request or http_request or (syn and syn.request) or (http and http.request)
		local body
		if type(fn) == "function" then
			local ok, res = pcall(fn, { Url = AUTH_URL, Method = "GET" })
			if ok and type(res) == "table" then body = res.Body end
		end
		if not body then
			local ok2, b2 = pcall(function() return game:HttpGet(AUTH_URL) end)
			if ok2 then body = b2 end
		end
		if type(body) ~= "string" or body == "" or body == "null" then return end
		local ok3, data = pcall(function() return HttpService:JSONDecode(body) end)
		if not ok3 or type(data) ~= "table" then return end
		if data.enabled == false then
			allowed, reason = false, tostring(data.message or "This script has been turned off by its owner.")
			return
		end
		local banned = data.banned
		if type(banned) == "table" then
			local uid, name = tostring(LP.UserId), LP.Name
			if banned[uid] or banned[name] then
				allowed, reason = false, "You have been blocked from using this script."
			end
		end
		-- a copy older than this gets replaced instead of just refused: a frozen autoexec/queued-teleport save can
		-- never pick up anything new on its own, no matter what ships later, because it is running whatever code
		-- existed the moment it was saved - there is no way to reach back into a copy that old and make it check
		-- anything it does not already know to check. Every copy from here on checks this on its own, every time,
		-- so the oldest a stuck copy can ever get stuck at again is whatever version first shipped this check.
		local minV = data.minVersion
		if allowed and type(minV) == "string" then
			local function num(v)
				local maj, minr = string.match(tostring(v), "v?(%d+)%.?(%d*)")
				return (tonumber(maj) or 0) * 1000 + (tonumber(minr) or 0)
			end
			if num(VERSION) < num(minV) then
				-- delete every saved copy of this script this exact code knows how to find, on its way out, whether
				-- the GitHub self-update below works or not - an old copy that keeps getting autoexec'd or queued
				-- back onto a teleport is exactly what was making it "spam load" the old version no matter what got
				-- published, so this makes sure it cannot fire itself again after this run, autoexec setting or not
				pcall(function()
					for _, folder in ipairs({ "autoexec", "Autoexec", "autoexecute", "Autoexecute" }) do
						pcall(function()
							local p = folder .. "/JHubV1_Glass.lua"
							if type(isfile) == "function" and isfile(p) and type(delfile) == "function" then delfile(p) end
						end)
					end
					pcall(function()
						local p = "JHubGlass/JHubV1_Glass.lua"
						if type(isfile) == "function" and isfile(p) and type(delfile) == "function" then delfile(p) end
					end)
				end)
				local updated = false
				pcall(function()
					local shaBody = game:HttpGet("https://api.github.com/repos/jaydendagoat2/jayhubv1/commits/claude%2Fclaudechud-8cord-executor-wclom3")
					local sha = type(shaBody) == "string" and string.match(shaBody, '"sha"%s*:%s*"(%x+)"')
					local url = sha and ("https://raw.githubusercontent.com/jaydendagoat2/jayhubv1/" .. sha .. "/J.lua")
						or "https://raw.githubusercontent.com/jaydendagoat2/jayhubv1/claude/j/J.lua"
					local src = game:HttpGet(url)
					if type(src) == "string" and #src > 10000 then
						local fn = loadstring(src)
						if fn then
							updated = true
							task.defer(fn)
						end
					end
				end)
				if updated then return end
				allowed, reason = false, "This copy is too old, was deleted from your autoexec folder, and could not reach GitHub to update itself. Rejoin once you're back online, or paste the loadstring yourself."
			end
		end
	end)
	if not allowed then
		pcall(function()
			local sg = Instance.new("ScreenGui")
			sg.Name = "JHubBlocked"
			sg.ResetOnSpawn = false
			local ok = pcall(function() sg.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
			if not ok or not sg.Parent then sg.Parent = LP:WaitForChild("PlayerGui") end
			local t = Instance.new("TextLabel")
			t.Size = UDim2.fromOffset(360, 60)
			t.Position = UDim2.new(0.5, -180, 0, 20)
			t.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
			t.TextColor3 = Color3.new(1, 1, 1)
			t.Font = Enum.Font.GothamBold
			t.TextSize = 14
			t.TextWrapped = true
			t.Text = reason or "This script is not available right now."
			t.Parent = sg
		end)
		return
	end
end

local function cam() return workspace.CurrentCamera end

local function bind(signal, fn)
	local c = signal:Connect(fn)
	table.insert(JH.Connections, c)
	return c
end
local function log(msg)
	msg = tostring(msg)
	table.insert(JH.Logs, 1, os.date("%H:%M:%S") .. "  " .. msg)
	if #JH.Logs > 60 then table.remove(JH.Logs) end
	if JH.RecLog then JH.RecLog(msg) end
	print("[JHub] " .. msg)
end
local function clamp(v, a, b)
	if v < a then return a elseif v > b then return b end
	return v
end
local function trim(s) return (string.gsub(s or "", "^%s*(.-)%s*$", "%1")) end
local function tokens(s)
	local out = {}
	for t in string.gmatch(s or "", "[^%s,]+") do table.insert(out, t) end
	return out
end
local function matchAny(s, words)
	for _, w in ipairs(words) do
		if string.find(s, w, 1, true) then return true end
	end
	return false
end
local function flat(v) return Vector3.new(v.X, 0, v.Z) end
local function new(class, props)
	local o = Instance.new(class)
	local parent
	if props then
		for k, v in pairs(props) do
			if k == "Parent" then parent = v else o[k] = v end
		end
	end
	if parent then o.Parent = parent end
	return o
end
local function visibleChain(g)
	local o = g
	while o and o ~= game do
		if o:IsA("GuiObject") and not o.Visible then return false end
		if o:IsA("LayerCollector") then return o.Enabled end
		o = o.Parent
	end
	return true
end
local function char()
	local c = LP.Character
	if c then return c end
	local f = workspace:FindFirstChild("Characters")
	return f and f:FindFirstChild(LP.Name)
end
local function hrp() local c = char() return c and (c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart) end
local function hum() local c = char() return c and c:FindFirstChildOfClass("Humanoid") end
local function insetHeight()
	local ok, v = pcall(function() return (GuiService:GetGuiInset()) end)
	return (ok and v) and v.Y or 0
end

