	UI.Toggle(al, "Sounds", "Sounds")
	UI.Keybind(al, "Menu key (PC)", function() return S.MenuKey end, function(v) S.MenuKey = (v ~= "" and v) or "RightShift" end)

	local tl = UI.Card(P, "Tools")
