	local ok, err = pcall(Speed.step, dt)
	if not ok and Speed.lastErr ~= tostring(err) then
		Speed.lastErr = tostring(err)
		log("Speed error: " .. Speed.lastErr)
		notify("Speed problem", Speed.lastErr, 5)
