			end
			local dbg = Bot.dbg or {}
			local dbgLine = string.format("dbgTarget=%s dbgDist=%s dbgDir=%s dbgSent=%s dbgSentOk=%s dbgSentVia=%s dbgHumState=%s dbgBlockedReason=%s",
