local keys = {}
for k in pairs(data) do keys[#keys + 1] = k end
table.sort(keys)
for _, c in ipairs(chatList:GetChildren()) do if c:IsA("TextLabel") then c:Destroy() end end
for i = math.max(1, #keys - 29), #keys do
