					if sanitize(lk) == k then realKey = lk break end
				end
JH.hardLocked[realKey] = true
JH.netLocked[realKey] = true
addHard(realKey)
				Shot.auto = Shot.auto or {}
				local a = Shot.auto[realKey] or { greens = {}, dir = 1, bin = S.PeakBin }
				a.hold, a.locked, a.mode = v.lead, true, "peak"
				Shot.auto[realKey] = a
				pcall(Shot.autoSave)
			end
		end
		task.wait(5)
	end
end)
-- a shot someone else is still learning: start yours from the middle of what players have found so far
task.spawn(function()
while JH.Running do
