for lk, a in pairs(Shot.auto or {}) do
if a.mode == "peak" and not a.locked and (a.n or 0) < 3 and sanitize(lk) == k then a.hold = clamp(v.lead, 0, 0.1) end
end
end
end
task.wait(5)
end
