-- LIVE ADAPT, SHARPER: steps shrink the more a jumpshot has actually been seen (so it locks in fast early, then stops wobbling), and one freak result against a steady trend gets a lighter step, not a full swing
do
local prevGainLA = Shot.adaptGain
local dampenKey, dampenUntil = nil, 0
function Shot.adaptGain(key, off)
local g = prevGainLA(key, off)
local a = Shot.auto and Shot.auto[key]
local n = a and a.n or 0
local decay = 1 / (1 + 0.12 * n)
g = g * clamp(decay, 0.2, 1)
if key == dampenKey and tick() < dampenUntil then g = g * 0.4 end
return g
end
local recent = {}
local prevLearnLA = Shot.autoLearn
function Shot.autoLearn(info, res, strength)
if info and info.key and info.idx and not info.manual then
local off = (info.idx == 5 and 0) or (info.idx == 4 and -1) or (info.idx - 5)
local h = recent[info.key] or {}
h[#h + 1] = off
while #h > 3 do table.remove(h, 1) end
recent[info.key] = h
if #h >= 3 then
local sum = 0
for i = 1, #h - 1 do sum = sum + h[i] end
local avg = sum / (#h - 1)
if math.abs(off) >= 3 and math.abs(avg) <= 1 then
dampenKey, dampenUntil = info.key, tick() + 1
end
end
end
return prevLearnLA(info, res, strength)
end
end
-- GREEN SOUNDS: add your own sound. Roblox blocks a lot of audio IDs inside games, so a sound can also be added from a direct link to an
-- .mp3/.ogg/.wav file: it is downloaded to your executor folder and played from there. Every sound is loaded and checked here: it must load and be 5 seconds or shorter.
do
local gp
for _, p in ipairs(UI.pages) do if p.name == "Green Sounds" then gp = p end end
if gp then
local MAXLEN = 5
local assetCache = {}
-- a stored sound is either a Roblox audio number or "f:filename" (a downloaded file)
local function soundIdOfKey(key)
local fname = string.match(tostring(key or ""), "^f:(.+)$")
if fname then
if assetCache[fname] then return assetCache[fname] end
if type(getcustomasset) ~= "function" then return nil end
if type(isfile) == "function" and not isfile(fname) then return nil end
local ok, a = pcall(getcustomasset, fname)
if ok and a and a ~= "" then assetCache[fname] = a return a end
return nil
end
local digits = string.match(tostring(key or ""), "%d+")
return digits and ("rbxassetid://" .. digits) or nil
end
local function measure(soundId)
local snd = Instance.new("Sound")
snd.SoundId = soundId
snd.Volume = 0
snd.Parent = game:GetService("SoundService")
pcall(function() game:GetService("ContentProvider"):PreloadAsync({ snd }) end)
local t0 = tick()
while tick() - t0 < 5 and not (snd.IsLoaded and snd.TimeLength > 0) do task.wait(0.1) end
local len = snd.IsLoaded and snd.TimeLength or 0
snd:Destroy()
return len
end
local function preview(soundId, vol)
if not soundId then return false end
local snd = Instance.new("Sound")
snd.SoundId = soundId
snd.Volume = vol or S.GreenSoundVol or 0.6
snd.Parent = game:GetService("SoundService")
snd:Play()
task.delay(6, function() pcall(function() snd:Destroy() end) end)
return true
end
