local lastFileGreen = 0
local prevPlay = JH.playGreenSound
function JH.playGreenSound(force)
if string.match(tostring(S.GreenSoundId or ""), "^f:") then
if not force then
if S.GreenSound == false or S.Sounds == false then return end
if tick() - lastFileGreen < 0.8 then return end
end
lastFileGreen = tick()
preview(soundIdOfKey(S.GreenSoundId), S.GreenSoundVol)
return
end
if prevPlay then return prevPlay(force) end
end
local list = {}
for key, name in string.gmatch(S.CustomSounds or "", "([^=;]+)=([^;]*);") do list[#list + 1] = { id = key, name = name } end
local function save()
local p = {}
for _, e in ipairs(list) do p[#p + 1] = e.id .. "=" .. e.name .. ";" end
S.CustomSounds = table.concat(p)
saveSoon()
end
local function picked()
for _, e in ipairs(list) do if e.name == S.CustomPick then return e end end
end
