local card = UI.Card(gp, "Add your own sound")
UI.Note(card, "Paste a Roblox audio ID, or a direct link to an .mp3 / .ogg / .wav file (a link works even when Roblox blocks the audio ID). It is loaded here first: if it does not load, or it is longer than 5 seconds, it is not added.")
UI.Input(card, "Sound ID or link", { get = function() return newId end, set = function(v) newId = tostring(v or "") end }, nil, "audio number or https link")
UI.Input(card, "Name", { get = function() return newName end, set = function(v) newName = tostring(v or "") end }, nil, "what to call it")
UI.Button(card, "Test and add", function()
local key, soundId
local url = string.match(newId, "^%s*(https?://%S+)")
if url then
if type(writefile) ~= "function" or type(getcustomasset) ~= "function" then notify("Green sound", "This executor cannot play sound files. Use a Roblox audio ID instead.", 5) return end
notify("Green sound", "Downloading...", 2)
local okd, data = pcall(function() return game:HttpGet(url) end)
if not okd or type(data) ~= "string" or #data < 200 then notify("Green sound", "Could not download that link.", 5) return end
if #data > 1500000 then notify("Green sound", "That file is too big for a 5 second sound.", 5) return end
local ext = string.lower(string.match(url, "%.(%w+)[%?#]?[^/%.]*$") or "mp3")
if ext ~= "mp3" and ext ~= "ogg" and ext ~= "wav" then ext = "mp3" end
local fname = "JHub_sound_" .. tostring(os.time()) .. "." .. ext
if not pcall(writefile, fname, data) then notify("Green sound", "Could not save the file.", 5) return end
key = "f:" .. fname
soundId = soundIdOfKey(key)
if not soundId then notify("Green sound", "Could not read the downloaded file.", 5) return end
else
local id = string.match(newId, "%d+")
if not id then notify("Green sound", "Type a sound ID or a link first", 3) return end
key = id
soundId = soundIdOfKey(key)
end
for _, e in ipairs(list) do
if e.id == key then notify("Green sound", "That sound is already in your list", 3) return end
end
notify("Green sound", "Checking the sound...", 2)
local len = measure(soundId)
if len <= 0 then notify("Green sound", url and "The file did not play." or "That sound did not load (removed, private, or blocked by Roblox for this game). Try a direct file link instead.", 6) return end
if len > MAXLEN then notify("Green sound", string.format("Too long: %.1f seconds. A green sound has to be %d seconds or shorter.", len, MAXLEN), 6) return end
local name = string.gsub(newName, "[^%w %-_]", "")
if name == "" then name = url and "My sound" or ("Sound " .. key) end
list[#list + 1] = { id = key, name = name }
save()
notify("Green sound", string.format("Added %s (%.1f seconds)", name, len), 4)
preview(soundId)
end, true)
UI.Dropdown(card, "Your sounds", "CustomPick", function()
local o = {}
for _, e in ipairs(list) do o[#o + 1] = e.name end
return o
