do
	local plan = {}
	-- owner codes are only compared as hashes, never stored as text
	JH.hash = function(s)
		s = tostring(s or "")
		local h = 5381
		local function mix(str) for i = 1, #str do h = (h * 131 + string.byte(str, i)) % 4294967291 end end
		mix("jhv1|" .. s) mix("|1hvhj")
		return "H" .. string.format("%d", h)
	end
	local function find(name)
		for i, p in ipairs(UI.pages) do
			if p.name == name then return p, i end
		end
	end

	-- the extra helpers' own defense page doubled up Auto Guard, Block, Steal and Rebound: it goes away, JHub's versions stay
	do
		local dup, di = find("Defense")
		local keep = find("Auto Guard")
		if dup and keep and dup ~= keep then
			pcall(function() dup.bg.Parent:Destroy() end)
			pcall(function() dup.frame:Destroy() end)
			table.remove(UI.pages, di)
