							n = n + 1
							child.Parent = target.frame
						end
					end
					pcall(function() src.bg.Parent:Destroy() end)
					pcall(function() src.frame:Destroy() end)
					table.remove(UI.pages, idx)
				end
			end
			if row[2] then
				target.name = row[2]
				pcall(function() target.lbl.Text = row[2] end)
			end
		end
	end

	-- the Defense page: plain card names, a sensible order, the recorder and auto-play cards hidden, more room between cards
	do
		local d = find("Defense")
		if d then task.delay(1, function()
			local ORDER = { ["Auto guard"] = 1, ["Auto block"] = 2, ["Auto steal"] = 3 }
			local RENAME = { ["Auto guard"] = "Guard him (stay in front)", ["Auto block"] = "Block his shot", ["Auto steal"] = "Steal" }
			local HIDE = { ["Remote Guard Recorder"] = true, ["Auto play"] = true, ["Auto Guard (locked)"] = true }
			local nextOrder = 10
			for _, c in ipairs(d.frame:GetChildren()) do
				if c:IsA("Frame") then
					local title
					for _, l in ipairs(c:GetDescendants()) do
						if l:IsA("TextLabel") then title = l break end
					end
					local name = title and title.Text
					if name and HIDE[name] then
						c.Visible = false
					else
						if name and RENAME[name] then title.Text = RENAME[name] end
						c.LayoutOrder = (name and ORDER[name]) or nextOrder
						nextOrder = nextOrder + 1
					end
				end
			end
		end) end
		for _, p in ipairs(UI.pages) do
			local lay = p.frame:FindFirstChildOfClass("UIListLayout")
			if lay then lay.Padding = UDim.new(0, 14) end
		end
	end

	-- EMPTY MENU: every tab is removed except the ones asked for. Features keep their saved settings.
	do
		local KEEP = { Main = true, Shooting = true, ["Ball Mags"] = true, Features = true, ["Green Sounds"] = true, Graphics = true, Binds = true, Owner = true, Settings = true, UI = true }
		local kept
		for i = #UI.pages, 1, -1 do
			local p = UI.pages[i]
