		else
			UI.current = nil
			local blank = UI.Page("Start", "S")
			local card = UI.Card(blank, "Empty for now")
			UI.Note(card, "All tabs were removed. Tell me what to put back.")
		end
	end
	-- SHOOTING TAB: Auto Green, Auto Calibrate, Pick your best timer, Lag sync, and the Custom meter
	do
		local shoot = find("Shooting")
		if shoot then
			if getgenv and getgenv().JHDEBUG_ON then getgenv().JHDebug = { S = S, Shot = Shot, UI = UI, Lag = Lag, Feat = Feat, Bot = Bot, Input = Input } end
			-- everything that was on this tab keeps working underneath; only the four switches and the meter show
			for _, c in ipairs(shoot.frame:GetChildren()) do
				if c:IsA("GuiObject") then c.Visible = false end
			end
			local function setAll(keys, v)
				for _, k in ipairs(keys) do
					S[k] = v
					pcall(UI.set, k, v, false)
				end
			end
			local BEST = { "AllJumpers" }
			local LAG = { "LagSync", "AutoTiming" }
			local OFF = { "GreenMax", "AdaptPlus", "PrecFit", "InstantGreen", "AutoAdaptAll", "SmartSteps" }
			if S.ShootTabV ~= 2 then
				S.ShootTabV = 2
				setAll(OFF, false)
				S.AutoGreen, S.AutoCalibrate, S.BestTimer, S.LagSyncAll = true, true, true, true
				setAll(BEST, true)
				setAll(LAG, true)
				pcall(UI.syncAuto)
				saveSoon()
			end


			-- less work every frame: the extra helpers (no menu now) and the two options that re-check parts as the camera turns
			if S.TidyV ~= 1 then
				S.TidyV = 1
				S.ExtrasOn = false
				pcall(UI.set, "GfxCull", false, true)
				pcall(UI.set, "GfxHideOthers", false, true)
				S.GfxCull, S.GfxHideOthers = false, false
				saveSoon()
			end
			if S.ExtrasOn == false and JH.OK and JH.OK.stop then pcall(JH.OK.stop) end

			-- CUSTOM METER: the game's own meter changes into any meter the game has. One meter, changed in place, so nothing doubles
			local METERS = { "Vertical", "Bat", "Rocket", "Funnel", "Funnel2", "Pill", "Arrow", "Hoop", "Roblox", "Tube", "Diamond" }
			if S.CustomMeter == nil then S.CustomMeter = "Vertical" end
			if S.MeterSize == nil then S.MeterSize = 1 end
			if S.MeterR == nil then S.MeterR, S.MeterG, S.MeterB = 255, 255, 255 end
			local c5 = UI.Card(shoot, "Custom meter")
			c5.frame.LayoutOrder = 900
			UI.Toggle(c5, "Custom meter", "CustomMeterOn")
			UI.Dropdown(c5, "Meter", "CustomMeter", METERS)
			UI.Note(c5, "Only you see it.")
			local c6 = UI.Card(shoot, "Meter look")
			c6.frame.LayoutOrder = 901
			UI.Slider(c6, "Meter size", "MeterSize", 0.5, 3, 0.05, 2, "x")
			UI.Toggle(c6, "Custom meter color", "MeterColorOn")
			UI.Slider(c6, "Red", "MeterR", 0, 255, 5, 0)
			UI.Slider(c6, "Green", "MeterG", 0, 255, 5, 0)
			UI.Slider(c6, "Blue", "MeterB", 0, 255, 5, 0)
			for _, c in ipairs({ c5, c6 }) do c.frame.Size = UDim2.new(0.5, -6, 0, 0) end

			local IMG = { "Image", "ImageRectOffset", "ImageRectSize", "ScaleType", "SliceCenter", "Size", "Position", "AnchorPoint", "Rotation", "ZIndex" }
			local GUIP = { "Size", "StudsOffset", "ExtentsOffset", "LightInfluence", "AlwaysOnTop" }
			local snaps = {}      -- gui -> { props, children = { child -> props }, added = {}, hidden = {} }
			local swapped = {}    -- gui -> the meter name it currently looks like
			local yRot = {}       -- gui -> rotation to keep on its fill gradient
			local conns = {}
			local function readProps(o, list)
				local t = {}
				for _, p in ipairs(list) do
					local ok, v = pcall(function() return o[p] end)
					if ok then t[p] = v end
				end
				return t
			end
			local function writeProps(o, t)
				for p, v in pairs(t) do pcall(function() o[p] = v end) end
			end
			local function guiOf(ch, name)
				local r = ch:FindFirstChild("HumanoidRootPart")
				local g = r and r:FindFirstChild(name .. "Meter")
				if g then return g end
				local h = ch:FindFirstChild("Head")
				return h and h:FindFirstChild(name .. "Meter")
			end
			local function equipped(ch)
				local ok, mod = pcall(function() return require(LP.PlayerScripts.Aero.Controllers.Meter) end)
				local pk = ok and type(mod) == "table" and mod.ActivePackets and mod.ActivePackets[ch]
				if pk and pk.meterType then S.GameMeter = pk.meterType end
				return S.GameMeter
			end
			local function snapshot(g)
				if snaps[g] then return end
				local s = { props = readProps(g, GUIP), children = {}, added = {}, hidden = {}, grads = {} }
				for _, c in ipairs(g:GetChildren()) do
					if c:IsA("ImageLabel") then
						s.children[c] = readProps(c, IMG)
						s.children[c].ImageColor3 = c.ImageColor3
					elseif c:IsA("UIGradient") then
						s.grads[c] = { Color = c.Color }
					end
				end
				snaps[g] = s
			end
			local function restore(g)
				local s = snaps[g]
				if not s then return end
				writeProps(g, s.props)
				for c, p in pairs(s.children) do
					if c.Parent then writeProps(c, p) end
				end
				for c, p in pairs(s.grads) do
					if c.Parent then writeProps(c, p) end
				end
				for _, c in ipairs(s.added) do pcall(function() c:Destroy() end) end
				for c, v in pairs(s.hidden) do if c.Parent then c.Visible = v end end
				g:SetAttribute("JHSX", nil)
				g:SetAttribute("JHSY", nil)
				swapped[g] = nil
				yRot[g] = nil
			end
			local function becomeLike(g, y)
				snapshot(g)
				writeProps(g, readProps(y, GUIP))
				local s = snaps[g]
				for _, yc in ipairs(y:GetChildren()) do
					if yc:IsA("ImageLabel") then
						local gc = g:FindFirstChild(yc.Name)
						if not gc then
							gc = yc:Clone()
							gc.ImageTransparency = 1
							gc.Parent = g
							s.added[#s.added + 1] = gc
						else
							writeProps(gc, readProps(yc, IMG))
							gc.ImageColor3 = yc.ImageColor3
						end
					elseif yc:IsA("UIGradient") and g:FindFirstChild(yc.Name) then
						g[yc.Name].Color = yc.Color
					end
				end
				local gradY = y:FindFirstChild("FillGradient", true)
				local gradG = g:FindFirstChild("FillGradient", true)
				for _, gc in ipairs(g:GetChildren()) do
					if gc:IsA("ImageLabel") and not y:FindFirstChild(gc.Name) and not table.find(s.added, gc) then
						s.hidden[gc] = gc.Visible
						gc.Visible = false
					end
				end
				if gradG and gradY then
					yRot[g] = gradY.Rotation
					gradG.Rotation = gradY.Rotation
					conns[#conns + 1] = gradG:GetPropertyChangedSignal("Rotation"):Connect(function()
						if yRot[g] and gradG.Rotation ~= yRot[g] then gradG.Rotation = yRot[g] end
					end)
				end
				g:SetAttribute("JHSX", nil)
				g:SetAttribute("JHSY", nil)
				swapped[g] = y.Name
			end
			local function look(g)
				local s = snaps[g]
				local on = S.CustomMeterOn == true
				if not s then snapshot(g) s = snaps[g] end
				local base = swapped[g] and g:GetAttribute("JHBase") or nil
				if not g:GetAttribute("JHSX") then
					g:SetAttribute("JHSX", g.Size.X.Scale)
					g:SetAttribute("JHSY", g.Size.Y.Scale)
				end
				local k = on and (S.MeterSize or 1) or 1
				local bx, by = g:GetAttribute("JHSX"), g:GetAttribute("JHSY")
				if not bx or bx <= 0 then bx, by = g.Size.X.Scale, g.Size.Y.Scale end
				local want = UDim2.new(bx * k, g.Size.X.Offset, by * k, g.Size.Y.Offset)
				if g.Size ~= want then g.Size = want end
				local fill = g:FindFirstChild("Meter_Fill")
				if fill then
					local col
					if on and S.MeterColorOn == true then
						col = Color3.fromRGB(S.MeterR or 255, S.MeterG or 255, S.MeterB or 255)
					else
						col = (swapped[g] and fill.ImageColor3) or (s.children[fill] and s.children[fill].ImageColor3) or fill.ImageColor3
					end
					if fill.ImageColor3 ~= col and (on and S.MeterColorOn == true or not swapped[g]) then fill.ImageColor3 = col end
				end
			end
			local function refresh()
				local ch = char()
				if not ch then return end
				local X = equipped(ch)
				if not X then return end
				local gx = guiOf(ch, X)
				if not gx then return end
				local want = S.CustomMeterOn == true and S.CustomMeter or nil
				if want and want ~= X then
					if swapped[gx] ~= want then
						if swapped[gx] then restore(gx) end
						local y = guiOf(ch, want)
						if y then becomeLike(gx, y) end
					end
				elseif swapped[gx] or snaps[gx] then
					if swapped[gx] then restore(gx) end
				end
				if S.CustomMeterOn == true or snaps[gx] then pcall(look, gx) end
			end
			task.spawn(function()
				while JH.Running do
					pcall(refresh)
					task.wait(0.25)
				end
			end)
			local prevUnload = JH.Unload
			function JH.Unload()
				S.CustomMeterOn = false
				pcall(function()
					local ch = char()
					local X = ch and S.GameMeter
					local gx = X and guiOf(ch, X)
					if gx then
						restore(gx)
						local bx, by = gx:GetAttribute("JHSX"), gx:GetAttribute("JHSY")
						if bx then gx.Size = UDim2.new(bx, gx.Size.X.Offset, by, gx.Size.Y.Offset) end
					end
				end)
				for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
				if prevUnload then prevUnload() end
			end
		end
	end
-- FINAL MENU: the tabs, built fresh and kept compact. Old tabs are removed at the end.
	-- drag the whole menu from any side or the top
	do
		local function edge(name, pos, size, anchor)
			local f = Instance.new("Frame")
			f.Name = name f.BackgroundTransparency = 1 f.Position = pos f.Size = size f.AnchorPoint = anchor or Vector2.zero
			f.ZIndex = 50 f.Active = true f.Parent = Window
			dragify(f, Window, nil, UI.keepOnScreen, function() return WinScale.Scale end)
		end
		edge("DragTop", UDim2.fromScale(0, 0), UDim2.new(1, 0, 0, 14))
		edge("DragBottom", UDim2.fromScale(0, 1), UDim2.new(1, 0, 0, 12), Vector2.new(0, 1))
		edge("DragLeft", UDim2.fromScale(0, 0), UDim2.new(0, 10, 1, 0))
		edge("DragRight", UDim2.fromScale(1, 0), UDim2.new(0, 10, 1, 0), Vector2.new(1, 0))
	end
do
	local RunService = game:GetService("RunService")
	local function find(name)
		for i, p in ipairs(UI.pages) do
			if p.name == name then return p, i end
		end
	end
	if getgenv and getgenv().JHDEBUG_ON then getgenv().JHDebug = { S = S, Shot = Shot, UI = UI, Lag = Lag, Feat = Feat, Bot = Bot, Input = Input, DEFAULTS = DEFAULTS } end

	---------------------------------------------------------------------
	-- helpers: one place that keeps the extra helpers running only while something needs them
	---------------------------------------------------------------------
	local HELPER_FLAGS = {}
	local function helperFlag(f) HELPER_FLAGS[#HELPER_FLAGS + 1] = f end
	local function syncHelpers()
		local need = false
		for _, f in ipairs(HELPER_FLAGS) do
			if S[f] == true then need = true break end
		end
		local ok = JH.OK
		if not ok then return end
		if need and not ok.running then pcall(ok.start) end
		if not need and ok.running then pcall(ok.stop) end
	end

	---------------------------------------------------------------------
	-- framework: tabs, compact two-column cards, flag tracking for the Reset button
	---------------------------------------------------------------------
	local Tabs = {}
	local function newTab(name, glyph)
		local p = find(name) or UI.Page(name, glyph)
		p.order = 0
		local lay = p.frame:FindFirstChildOfClass("UIListLayout")
		if lay then
			lay.FillDirection = Enum.FillDirection.Horizontal
			lay.Wraps = true
			lay.Padding = UDim.new(0, 8)
			lay.HorizontalAlignment = Enum.HorizontalAlignment.Left
			lay.VerticalAlignment = Enum.VerticalAlignment.Top
		end
		local t = { page = p, flags = {}, defaults = {}, name = name, after = nil }
		Tabs[#Tabs + 1] = t
		return t
	end
	local function card(t, title, full)
		local c = UI.Card(t.page, title)
		for _, ch in ipairs(c.frame:GetChildren()) do
			if ch:IsA("UIStroke") then ch:Destroy() end
		end
		local pad = c.frame:FindFirstChildOfClass("UIPadding")
		if pad then
			pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 4), UDim.new(0, 4)
			pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 6), UDim.new(0, 6)
		end
		local ll = c.frame:FindFirstChildOfClass("UIListLayout")
		if ll then ll.Padding = UDim.new(0, 2) end
		c.frame.Size = full and UDim2.new(1, -4, 0, 0) or UDim2.new(0.5, -6, 0, 0)
		c.tab = t
		t.page.order = (t.page.order or 0) + 10
		c.frame.LayoutOrder = t.page.order
		return c
	end
	local function track(c, flag, default)
		local t = c.tab
		if type(flag) == "string" and not t.flags[flag] then
			t.flags[flag] = true
			t.flags[#t.flags + 1] = flag
			if default ~= nil then t.defaults[flag] = default end
		end
	end
	local function tog(c, text, flag, cb, default)
		track(c, flag, default)
		return UI.Toggle(c, text, flag, cb)
	end
	local function sld(c, text, flag, mn, mx, step, dec, suffix, cb, default)
		track(c, flag, default)
		return UI.Slider(c, text, flag, mn, mx, step, dec, suffix, cb)
	end
	local function drop(c, text, flag, options, cb, default)
		track(c, flag, default)
		return UI.Dropdown(c, text, flag, options, cb)
	end
	local function note(c, text) return UI.Note(c, text) end
	local function seed(flag, v) if S[flag] == nil then S[flag] = v end end
	local function resetCard(t)
		local c = card(t, "Reset", true)
		c.frame.LayoutOrder = 999
		UI.Button(c, "Reset this tab", function()
			for _, f in ipairs(t.flags) do
				local d = t.defaults[f]
				if d == nil then d = DEFAULTS[f] end
				S[f] = d
				pcall(UI.set, f, d, false)
			end
			if t.after then pcall(t.after) end
			syncHelpers()
			pcall(UI.refreshAll)
			saveSoon()
			notify("JHub", t.name .. " is back to default", 2)
		end)
		return c
	end

	---------------------------------------------------------------------
	-- SHOOTING
	---------------------------------------------------------------------
	local BEST = { "AllJumpers" }
	local LAG = { "LagSync", "AutoTiming" }
	local OFF = { "GreenMax", "AdaptPlus", "PrecFit", "InstantGreen", "AutoAdaptAll", "SmartSteps" }
	local function setAll(keys, v)
		for _, k in ipairs(keys) do
			S[k] = v
			pcall(UI.set, k, v, false)
		end
	end
	if S.ShootTabV ~= 3 then
		S.ShootTabV = 3
		S.X_AutoGreen, S.X_AutoCalibrate = true, true
		saveSoon()
	end
	-- JayHub's own Auto Green core stays off: the Auto Green below is the one that shoots
	S.AutoGreen, S.AutoCalibrate = false, false
	pcall(UI.syncAuto)
	local shoot = newTab("Shooting", "S")
	shoot.after = function()
		S.AutoGreen, S.AutoCalibrate = false, false
		S.X_AutoGreen, S.X_AutoCalibrate = true, true
	end
	do
		local c = card(shoot, "Auto Green")
		helperFlag("X_AutoGreen") helperFlag("X_AutoCalibrate")
		tog(c, "Auto Green", "X_AutoGreen", function() syncHelpers() end, true)
		note(c, "Releases the shot on the green.")
		c = card(shoot, "Auto Calibrate")
		tog(c, "Auto Calibrate", "X_AutoCalibrate", function() syncHelpers() end, true)
		c = card(shoot, "Pick your best timer")
		tog(c, "Pick your best timer", "BestTimer", function(v) setAll(BEST, v == true) end, true)
		note(c, "Spots your jump shot and picks its best timing.")
		c = card(shoot, "Lag sync")
		tog(c, "Lag sync", "LagSyncAll", function(v) setAll(LAG, v == true) end, true)
		note(c, "Follows your ping and FPS by itself.")

		-- CONTEST: how open a player is. Red = covered, orange = a bit open, green = open. Works on you and on the other team
		seed("ContestOn", false) seed("ContestHead", true) seed("ContestGlow", true) seed("ContestGround", true) seed("ContestFoes", true)
		c = card(shoot, "Contest")
		tog(c, "Show contest", "ContestOn", nil, false)
		tog(c, "Number over the head", "ContestHead", nil, true)
		tog(c, "Color on the player", "ContestGlow", nil, true)
		tog(c, "Marker on the ground", "ContestGround", nil, true)
		tog(c, "Do it for opponents too", "ContestFoes", nil, true)
		note(c, "Red = covered, orange = kind of open, green = open.")
	end
	-- the contest drawing itself
	do
		local RED, ORANGE, GREEN = Color3.fromRGB(235, 60, 60), Color3.fromRGB(255, 150, 40), Color3.fromRGB(70, 220, 110)
		local items = {}
		local folder
		local function kill(c)
			local it = items[c]
			if not it then return end
			for _, o in pairs(it) do pcall(function() o:Destroy() end) end
			items[c] = nil
		end
		local function killAll()
			for c in pairs(items) do kill(c) end
			if folder then pcall(function() folder:Destroy() end) folder = nil end
		end
		local function rootOf(c) return c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart end
		local function sideOf(c) return c:GetAttribute("HomeTeam") end
		local function shade(d)
			if d <= 5 then return RED, "COVERED" elseif d <= 10 then return ORANGE, "CLOSE" end
			return GREEN, "OPEN"
		end
		local function all()
			local list = {}
			local chars = workspace:FindFirstChild("Characters")
			if chars then
				for _, m in ipairs(chars:GetChildren()) do
					if m:IsA("Model") and m.Name ~= "InvisCharacter" then
						local r, h = rootOf(m), m:FindFirstChildOfClass("Humanoid")
						if r and h and h.Health > 0 then list[#list + 1] = m end
					end
				end
			end
			return list
		end
		local function show(c, d, isMe)
			local col, word = shade(d)
			local it = items[c]
			if not it then
				it = {}
				items[c] = it
				folder = folder or Instance.new("Folder")
				folder.Name = "JHContest"
				if not folder.Parent then folder.Parent = workspace.CurrentCamera end
				local r = rootOf(c)
				local bb = Instance.new("BillboardGui")
				bb.Size = UDim2.fromOffset(110, 34)
				bb.StudsOffset = Vector3.new(0, 4.4, 0)
				bb.AlwaysOnTop = true
				bb.Adornee = r
				bb.Parent = folder
				local tl = Instance.new("TextLabel")
				tl.Size = UDim2.fromScale(1, 1)
				tl.BackgroundTransparency = 1
				tl.Font = Enum.Font.GothamBold
				tl.TextSize = 16
				tl.TextStrokeTransparency = 0.3
				tl.Parent = bb
				it.bb, it.tl = bb, tl
				local hl = Instance.new("Highlight")
				hl.FillTransparency = 0.65
				hl.OutlineTransparency = 0.2
				hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
				hl.Adornee = c
				hl.Parent = folder
				it.hl = hl
				local ring = Instance.new("Part")
				ring.Shape = Enum.PartType.Cylinder
				ring.Size = Vector3.new(0.15, 5, 5)
				ring.Anchored, ring.CanCollide, ring.CanQuery, ring.CanTouch, ring.CastShadow = true, false, false, false, false
				ring.Material = Enum.Material.Neon
				ring.Transparency = 0.35
				ring.Parent = folder
				it.ring = ring
			end
			it.tl.Text = word .. " " .. math.floor(math.clamp((10 - d) / 10, 0, 1) * 100 + 0.5) .. "%"
			it.tl.TextColor3 = col
			it.bb.Enabled = S.ContestHead ~= false
			it.hl.FillColor, it.hl.OutlineColor = col, col
			it.hl.Enabled = S.ContestGlow ~= false
			it.ring.Color = col
			local r = rootOf(c)
			if r and it.ring then
				it.ring.Transparency = (S.ContestGround ~= false) and 0.35 or 1
				it.ring.CFrame = CFrame.new(r.Position - Vector3.new(0, 2.9, 0)) * CFrame.Angles(0, 0, math.rad(90))
			end
		end
		task.spawn(function()
			while JH.Running do
				if S.ContestOn == true then
					pcall(function()
						local list = all()
						local me = char()
						local mySide = me and sideOf(me)
						local seen = {}
						for _, c in ipairs(list) do
							local isMe = (c == me)
							local foe = (not isMe) and (mySide == nil or sideOf(c) ~= mySide)
							if isMe or (foe and S.ContestFoes ~= false) then
								local rc = rootOf(c)
								local best = math.huge
								for _, o in ipairs(list) do
									if o ~= c then
										local opp
										if isMe then opp = (mySide == nil or sideOf(o) ~= mySide)
										else opp = (sideOf(o) == mySide) or (o == me) or mySide == nil and false end
										if opp then
											local ro = rootOf(o)
											local dd = (ro.Position - rc.Position).Magnitude
											if dd < best then best = dd end
										end
									end
								end
								if best == math.huge then best = 30 end
								show(c, best, isMe)
								seen[c] = true
							end
						end
						for c in pairs(items) do if not seen[c] or not c.Parent then kill(c) end end
					end)
				else
					if next(items) then killAll() end
				end
				task.wait(0.15)
			end
			killAll()
		end)
	end
