end
	-- BATCH 2: ESP, Rebound, plus the older tabs kept, tidied, renamed, reset-buttoned and put in order
	do
		local Players = game:GetService("Players")
		local newTab, card, tog, sld, drop, note, resetCard, seed = JH.menuNew, JH.menuCard, JH.menuTog, JH.menuSld, JH.menuDrop, JH.menuNote, JH.menuReset, JH.menuSeed

		-------------------------------------------------------------
		-- ESP: lines and zones on the floor, drawn once and left alone
		-------------------------------------------------------------
		seed("ESP3", false) seed("ESPDunk", false) seed("ESPRange", false) seed("ESPBall", false) seed("ESPPlayers", false)
		seed("ESP3Dist", 26) seed("ESPDunkDist", 8) seed("ESPRangeDist", 8)
		local esp = newTab("ESP", "E")
		do
			local c = card(esp, "Lines and zones")
			tog(c, "3-point line", "ESP3", nil, false)
			sld(c, "3-point distance", "ESP3Dist", 15, 40, 0.5, 1, " studs", nil, 26)
			tog(c, "Dunk zones", "ESPDunk", nil, false)
			sld(c, "Dunk zone size", "ESPDunkDist", 4, 16, 0.5, 1, " studs", nil, 8)
			tog(c, "My range", "ESPRange", nil, false)
			sld(c, "My range size", "ESPRangeDist", 4, 30, 0.5, 1, " studs", nil, 8)
			c = card(esp, "Prediction")
			tog(c, "Ball prediction", "ESPBall", nil, false)
			tog(c, "Player prediction", "ESPPlayers", nil, false)
		end
		resetCard(esp)
		do
			local folder
			local rings = {}
			local function getFolder()
				if not folder or not folder.Parent then
					folder = Instance.new("Folder")
					folder.Name = "JHEsp"
					folder.Parent = workspace.CurrentCamera
				end
				return folder
			end
			local function part(parent, shape)
				local p = Instance.new("Part")
				p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
				p.Material = Enum.Material.Neon
				p.Shape = shape or Enum.PartType.Block
				p.Parent = parent
				return p
			end
			local function killRing(k)
				if rings[k] then pcall(function() rings[k].model:Destroy() end) rings[k] = nil end
			end
			local function floorY(pos)
				local rp = RaycastParams.new()
				rp.FilterType = Enum.RaycastFilterType.Exclude
				local ex = { workspace:FindFirstChild("Hoops"), workspace:FindFirstChild("Characters") }
				rp.FilterDescendantsInstances = ex
				local r = workspace:Raycast(pos, Vector3.new(0, -40, 0), rp)
				return r and r.Position.Y + 0.15 or pos.Y - 10
			end
			local function ring(key, center, radius, color)
				local r = rings[key]
				if r and r.radius == radius and (r.center - center).Magnitude < 0.5 then return end
				killRing(key)
				local m = Instance.new("Model") m.Name = key m.Parent = getFolder()
				local n = 56
				local seg = 2 * math.pi * radius / n
				for i = 0, n - 1 do
					local a = i / n * math.pi * 2
					local p = part(m)
					p.Size = Vector3.new(seg * 1.05, 0.15, 0.5)
					p.Color = color
					p.CFrame = CFrame.new(center + Vector3.new(math.cos(a) * radius, 0, math.sin(a) * radius)) * CFrame.Angles(0, -a + math.pi / 2, 0)
				end
				rings[key] = { model = m, radius = radius, center = center }
			end
			local rimsCache, rimsAt = {}, 0
			local function rims()
				if os.clock() - rimsAt > 3 then
					rimsAt = os.clock()
					rimsCache = {}
					local h = workspace:FindFirstChild("Hoops")
					if h then
						for _, hoop in ipairs(h:GetChildren()) do
							local r = hoop:FindFirstChild("Rim", true)
							if r and r:IsA("BasePart") then rimsCache[#rimsCache + 1] = r.Position end
						end
					end
				end
				return rimsCache
			end
			local disc, dots, pdots = nil, {}, {}
			local function ballPart()
				local b = workspace:FindFirstChild("Ball") or workspace:FindFirstChild("Basketball")
				if b and b:IsA("Model") then b = b.PrimaryPart or b:FindFirstChildWhichIsA("BasePart") end
				return b
			end
			task.spawn(function()
				while JH.Running do
					local any = S.ESP3 == true or S.ESPDunk == true or S.ESPRange == true or S.ESPBall == true or S.ESPPlayers == true
					if any then
						pcall(function()
							local fl = getFolder()
							local rs = rims()
							for i, rp in ipairs(rs) do
								local fy = floorY(rp)
								local center = Vector3.new(rp.X, fy, rp.Z)
								if S.ESP3 == true then ring("three" .. i, center, S.ESP3Dist or 26, Color3.fromRGB(255, 255, 255)) else killRing("three" .. i) end
								if S.ESPDunk == true then ring("dunk" .. i, center, S.ESPDunkDist or 8, Color3.fromRGB(255, 170, 40)) else killRing("dunk" .. i) end
							end
							local c = char()
							local root = c and c:FindFirstChild("HumanoidRootPart")
							if S.ESPRange == true and root then
								if not disc then disc = part(fl, Enum.PartType.Cylinder) disc.Transparency = 0.8 disc.Color = Color3.fromRGB(80, 200, 255) end
								local d = (S.ESPRangeDist or 8) * 2
								disc.Size = Vector3.new(0.15, d, d)
								disc.CFrame = CFrame.new(root.Position - Vector3.new(0, 2.8, 0)) * CFrame.Angles(0, 0, math.rad(90))
							elseif disc then disc:Destroy() disc = nil end
							if S.ESPBall == true then
								local b = ballPart()
								if b then
									local g = workspace.Gravity
									local v = b.AssemblyLinearVelocity
									for i = 1, 18 do
										local t = i * 0.07
										local p = dots[i]
										if not p then p = part(fl, Enum.PartType.Ball) p.Size = Vector3.new(0.6, 0.6, 0.6) p.Color = Color3.fromRGB(255, 120, 40) dots[i] = p end
										p.Transparency = v.Magnitude > 4 and 0.1 or 1
										p.Position = b.Position + v * t - Vector3.new(0, 0.5 * g * t * t, 0)
									end
								end
							else for i, p in pairs(dots) do p:Destroy() dots[i] = nil end end
							if S.ESPPlayers == true then
								local n = 0
								local cf = workspace:FindFirstChild("Characters")
								if cf then
									for _, m in ipairs(cf:GetChildren()) do
										local r = m ~= c and m:FindFirstChild("HumanoidRootPart")
										if r then
											n = n + 1
											local p = pdots[n]
											if not p then p = part(fl, Enum.PartType.Cylinder) p.Color = Color3.fromRGB(255, 80, 200) p.Transparency = 0.4 pdots[n] = p end
											local v = r.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
											p.Size = Vector3.new(0.15, 3, 3)
											p.CFrame = CFrame.new(r.Position + v * 0.5 - Vector3.new(0, 2.8, 0)) * CFrame.Angles(0, 0, math.rad(90))
										end
									end
								end
								for i = n + 1, #pdots do pdots[i]:Destroy() pdots[i] = nil end
							else for i, p in pairs(pdots) do p:Destroy() pdots[i] = nil end end
						end)
					else
						for k in pairs(rings) do killRing(k) end
						if disc then disc:Destroy() disc = nil end
						for i, p in pairs(dots) do p:Destroy() dots[i] = nil end
						for i, p in pairs(pdots) do p:Destroy() pdots[i] = nil end
					end
					task.wait(S.ESPBall == true and 0.05 or 0.15)
				end
				if folder then folder:Destroy() end
			end)
		end

		-------------------------------------------------------------
		-- REBOUND: speed is the game's own running speed, no slider
		-------------------------------------------------------------
		local reb = newTab("Rebound", "R")
		S.ARSpeed = 1
		do
