		-- the older tabs: borderless, two per row, reset button
		-------------------------------------------------------------
		local LISTS = {
			["Ball Mags"] = { "BallMagnet", "MagnetMode", "MagnetRange", "MagnetFrames", "MagnetDelay" },
			Features = { "LogoOn", "Logo", "MascotOn", "Mascot", "MaxOverall", "MaxCoins", "MaxBadges" },
			["Green Sounds"] = { "GreenSound", "GreenSoundId", "GreenSoundVol" },
			Graphics = { "GfxBoost", "GfxFpsCap", "GfxLow", "GfxTextures", "GfxEffects", "GfxShadows", "GfxPost", "GfxHideOthers", "GfxCull", "GfxCullDist", "PingStab", "PingWindow" },
			UI = { "WinTrans", "CardTrans", "Hue", "Sat", "Val", "OutlineColor", "OutlineThick", "OutlineShine", "OutlineTrans", "TextColor", "TextStroke", "Font", "Corner", "UIScale", "Watermark", "LogoSize", "LogoOpacity", "LogoAnim", "Preset", "AccentMode", "Lightning", "BgMove", "BgGlow", "BgOrbs", "Notifications", "Sounds" },
		}
		local RENAME = { Owner = "Owner/Admin", Settings = "Configs", UI = "UI Customizations" }
		for _, p in ipairs(UI.pages) do
			local list = LISTS[p.name]
			local isNew = false
			for _, t in ipairs(JH.menuTabs) do if t.page == p then isNew = true end end
			if not isNew and (list or p.name == "Binds" or p.name == "Owner" or p.name == "Settings") then
				for _, ch in ipairs(p.frame:GetChildren()) do
					if ch:IsA("Frame") then
						for _, s in ipairs(ch:GetChildren()) do if s:IsA("UIStroke") then s:Destroy() end end
						local pad = ch:FindFirstChildOfClass("UIPadding")
						if pad then pad.PaddingTop, pad.PaddingBottom, pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 4), UDim.new(0, 4), UDim.new(0, 6), UDim.new(0, 6) end
						local ll = ch:FindFirstChildOfClass("UIListLayout")
						if ll then ll.Padding = UDim.new(0, 2) end
						if ch.Size.X.Scale ~= 1 and not (ch.Size.X.Scale == 0.5) then ch.Size = UDim2.new(0.5, -6, 0, 0) end
					end
				end
				local lay = p.frame:FindFirstChildOfClass("UIListLayout")
				if lay then
					lay.FillDirection = Enum.FillDirection.Horizontal
					lay.Wraps = true
					lay.Padding = UDim.new(0, 8)
					lay.HorizontalAlignment = Enum.HorizontalAlignment.Left
					lay.VerticalAlignment = Enum.VerticalAlignment.Top
				end
				if list then
					local t = newTab(p.name)
					for _, f in ipairs(list) do t.flags[#t.flags + 1] = f t.flags[f] = true end
					resetCard(t)
				end
			end
			if RENAME[p.name] then
				p.name = RENAME[p.name]
				pcall(function() p.lbl.Text = p.name end)
			end
		end
		-- the old Restore cards are replaced by the Reset cards
		for _, p in ipairs(UI.pages) do
			for _, ch in ipairs(p.frame:GetChildren()) do
				if ch:IsA("Frame") then
					for _, d in ipairs(ch:GetDescendants()) do
						if d:IsA("TextLabel") and d.Text == "Restore" then pcall(function() ch:Destroy() end) break end
					end
				end
			end
		end

		-------------------------------------------------------------
		-- FEATURES: more mascots and Real Look
		-------------------------------------------------------------
		local feat = nil
		for _, p in ipairs(UI.pages) do if p.name == "Features" then feat = p end end
		if feat then
			local function C(r, g, b) return Color3.fromRGB(r, g, b) end
			local more = {
				Shrek = { skin = C(130, 180, 70), shirt = C(190, 170, 120), pants = C(110, 80, 50), label = "Shrek" },
				Minion = { skin = C(255, 220, 40), shirt = C(60, 100, 170), pants = C(60, 100, 170), eyes = true, label = "Minion" },
				Pikachu = { skin = C(255, 215, 50), shirt = C(255, 215, 50), pants = C(255, 215, 50), ears = C(255, 215, 50), label = "Pikachu" },
				Mario = { skin = C(240, 190, 150), shirt = C(220, 30, 30), pants = C(40, 70, 190), hat = C(220, 30, 30), label = "Mario" },
				Luigi = { skin = C(240, 190, 150), shirt = C(40, 160, 70), pants = C(40, 70, 190), hat = C(40, 160, 70), label = "Luigi" },
				Sonic = { skin = C(40, 90, 220), shirt = C(40, 90, 220), pants = C(40, 90, 220), label = "Sonic" },
				Kai = { skin = C(120, 80, 60), shirt = C(255, 255, 255), pants = C(30, 30, 30), label = "Kai Cenat" },
				Ninja = { skin = C(235, 195, 160), shirt = C(30, 90, 200), pants = C(30, 30, 30), label = "Ninja" },
				Markiplier = { skin = C(235, 195, 160), shirt = C(190, 30, 40), pants = C(30, 30, 30), label = "Markiplier" },
				PewDiePie = { skin = C(240, 200, 170), shirt = C(255, 255, 255), pants = C(60, 70, 120), label = "PewDiePie" },
				Peter = { skin = C(240, 200, 160), shirt = C(255, 255, 255), pants = C(110, 190, 120), label = "Peter Griffin" },
				Bluey = { skin = C(110, 160, 220), shirt = C(110, 160, 220), pants = C(110, 160, 220), label = "Bluey" },
				Elmo = { skin = C(220, 30, 40), shirt = C(220, 30, 40), pants = C(220, 30, 40), label = "Elmo" },
				Kermit = { skin = C(90, 180, 60), shirt = C(90, 180, 60), pants = C(90, 180, 60), label = "Kermit" },
			}
			local V = Feat.V
			for k, v in pairs(more) do
				if not V.MASCOTS[k] then V.MASCOTS[k] = v V.MASCOT_NAMES[#V.MASCOT_NAMES + 1] = k end
			end
			-- Real Look: copy someone's avatar (only you see it)
			local t
			for _, x in ipairs(JH.menuTabs) do if x.name == "Features" then t = x end end
			t = t or newTab("Features")
