	-- LAG PROOF: background network polling only runs when its card can be seen, and shared timing data is not polled at all
	do
		local lastRoles = 0
		JH.netSkip = function(path)
			if path == "timing" or path == "timing2" or path == "famtiming2" then return true end
			if path == "chat" or path == "presence" or path == "feed" then return true end
			if path == "roles" then
				local n = os.clock()
				if n - lastRoles < 60 then return true end
				lastRoles = n
			end
			return false
		end
	end
	-- ball magnet grabs the ball right away
