	-- ===== v2.53: glide + movement fixes =====
	do
		local STEPS = { "gather", "hop", "euro", "step", "side", "spin", "stepback", "pivot" }
		-- no speed boosts while the game has your movement locked (holding with two hands, shooting, gathering)
		local origStep = Speed.step
		function Speed.step(dt)
			local c = char()
			if c then
				local act = string.lower(tostring(c:GetAttribute("Action") or ""))
				if c:GetAttribute("CanMove") == false or matchAny(act, { "shoot", "layup", "dunk", "gather" }) then
					Speed.lastPos = nil
					Speed.seenLast = nil
					return
				end
			end
			return origStep(dt)
		end
		function Glide.gatherOk(c) return true end
		-- direction rules: follow where you are already going, never forward
		local function liveDir()
			local d = Mover.moveWhere(1.2)
			if d then return flat(d) end
			local h, r = hum(), Mover.body()
			if h and r then
				local okI, it = pcall(Mover.intent, h, r)
				if okI and it and it.Magnitude > 0.1 then return flat(it) end
			end
			return nil
		end
		local function noForward(dir, anim)
			local body = Mover.body()
			if not body then return dir end
			local look = flat(body.CFrame.LookVector).Unit
			local right = flat(body.CFrame.RightVector).Unit
			local a = string.lower(anim or "")
			if not dir or dir.Magnitude < 0.1 then
				if matchAny(a, { "fadeaway", "fade", "stepback", "step back" }) then
					if string.find(a, "left", 1, true) then return -right end
					if string.find(a, "right", 1, true) then return right end
					return -look
				end
				return nil
			end
			dir = dir.Unit
			local f = dir:Dot(look)
			if f > 0.25 then
				local side = dir - look * f
				if side.Magnitude < 0.2 then return nil end
				return side.Unit
			end
			return dir
		end
		function Mover.watchShot(pressT)
			task.defer(function()
				local c0 = char()
				local anim = tostring(c0 and c0:GetAttribute("BaseAnimation") or "")
				local dir = noForward(liveDir(), anim)
				if not dir then return end
				Glide.lastStart.shot = 0
				Glide.fire("shot", "shot", dir)
			end)
		end
		-- gather glide starts with the gather itself, for every kind of step
		local hookedFor
		local function hookChar()
			local c = char()
			if not c or hookedFor == c then return end
			hookedFor = c
			local function go(why)
				if not S.GatherGlide then return end
				local c2 = char()
				local a = string.lower(tostring(c2 and c2:GetAttribute("Action") or ""))
				local g = string.lower(tostring(c2 and c2:GetAttribute("GatherType") or ""))
				if a ~= "gathering" and not (g ~= "" and tick() - (Anim.lastDribble or 0) < 1.5) then return end
				Glide.lastStart.gather = 0
				pcall(Glide.fire, "gather", why, liveDir())
			end
			c:GetAttributeChangedSignal("GatherType"):Connect(function() go("gather type") end)
			c:GetAttributeChangedSignal("Action"):Connect(function()
				if c:GetAttribute("Action") == "Gathering" then go("gathering") end
			end)
		end
		task.spawn(function()
			while JH.Running do
				pcall(hookChar)
				task.wait(1)
			end
		end)
	end

	-- ===== v2.53b: shot glide only on real shots, chat tab, glide/boost master sliders =====
	do
		local function shooting()
			local c = char()
			if not c then return false end
			local a = string.lower(tostring(c:GetAttribute("Action") or ""))
			if matchAny(a, { "shoot", "layup", "dunk" }) then return true end
			local st = c:GetAttribute("ShotStartTime")
			if type(st) == "number" then
				if math.abs(workspace:GetServerTimeNow() - st) < 0.8 then return true end
			end
			return false
		end
		S.ShotGlideMethod = "CFrame"
		S.ShotGlideWhen = "During shot"
		local origFire = Glide.fire
		function Glide.fire(kind, why, dir)
			if kind == "shot" and not (Ball.holding and shooting()) then return end
			return origFire(kind, why, dir)
		end
		local baseWatch = Mover.watchShot
		function Mover.watchShot(pressT)
			task.spawn(function()
				local t0 = tick()
				while JH.Running and tick() - t0 < 0.4 and not (Ball.holding and shooting()) do RunService.Heartbeat:Wait() end
				if not (Ball.holding and shooting()) then return end
				baseWatch(pressT)
			end)
		end
		-- masters: scale every glide and every boost (1 = as set, lower for legit play)
		if S.GlideMaster == nil then S.GlideMaster = 1 end
		if S.BoostMaster == nil then S.BoostMaster = 1 end
		local origStart = Glide.start
		function Glide.start(kind, power, duration, dirOverride)
			return origStart(kind, power * (S.GlideMaster or 1), duration, dirOverride)
		end
		local origExtra = Speed.extraNow
		function Speed.extraNow()
			return origExtra() * (S.BoostMaster or 1)
		end
		local newTab, card, tog, sld, drop, note = JH.menuNew, JH.menuCard, JH.menuTog, JH.menuSld, JH.menuDrop, JH.menuNote
		local dt, ut
		for _, x in ipairs(JH.menuTabs) do
			if x.name == "Dribbling" then dt = x end
			if string.find(x.name, "UI", 1, true) then ut = x end
		end
		if dt then
			local tune = card(dt, "Legit tuning")
			sld(tune, "All glides (x)", "GlideMaster", 0, 1, 0.05, 2, "x", nil, 1)
			sld(tune, "All boosts (x)", "BoostMaster", 0, 1, 0.05, 2, "x", nil, 1)
			note(tune, "1 = as set. Lower it to glide and run less, for legit play. Each glide and boost slider also moves in 0.2 steps.")
		end

		-- LAG SWITCH: throttles what you send, so everyone else sees you frozen while you keep moving; releasing snaps you back
		do
			local ft
			ft = JH.menuNew("Lag Switch", "L")
			if ft then
				local UIS2 = game:GetService("UserInputService")
				local NC = game:GetService("NetworkClient")
				local lc = card(ft, "Lag Switch")
				local on, since = false, 0
				local function setLag(v)
					if v == on then return end
					on = v
					since = tick()
					pcall(function() NC:SetOutgoingKBPSLimit(v and 1 or 0) end)
					pcall(function() if setfflag then setfflag("DFIntS2PhysicsSenderRate", v and "1" or "15") end end)
					if v then
						task.spawn(function()
							while on and JH.Running do
								local rr = Mover.body()
								if rr then pcall(function() rr.Anchored = true end) end
								task.wait(S.LagStyle == "Stutter" and (0.5 + math.random() * 0.5) or 0.1)
								if S.LagStyle == "Stutter" and on then
									if rr then pcall(function() rr.Anchored = false end) end
									task.wait(0.06)
								end
							end
							local rr = Mover.body()
							if rr then pcall(function() rr.Anchored = false end) end
						end)
					else
						local rr = Mover.body()
						if rr then pcall(function() rr.Anchored = false end) end
					end
					notify("Lag Switch", v and "ON - others see you frozen" or "OFF - snapped back", 2)
				end
				JH.setLag = setLag
				drop(lc, "Style", "LagStyle", { "Freeze", "Stutter" }, nil, "Freeze")
				sld(lc, "Auto release after", "LagMax", 1, 15, 1, 0, "s", nil, 6)
				local capturing = false
				UI.Button(lc, "Set key (now: " .. tostring(S.LagKey or "L") .. ") - click, then press a key", function()
					capturing = true
					notify("Lag Switch", "Press the key you want to bind", 3)
				end, true)
				UIS2.InputBegan:Connect(function(i, gp)
					if capturing and i.UserInputType == Enum.UserInputType.Keyboard then
						capturing = false
						S.LagKey = i.KeyCode.Name
						saveSoon()
						notify("Lag Switch", "Bound to " .. S.LagKey, 3)
					end
				end)
				UI.Button(lc, "Lag on / off", function() setLag(not on) end, true)
				note(lc, "Press the key (or the button) to lag everyone else; press again or wait for the auto release to snap back.")
				UIS2.InputBegan:Connect(function(i, gp)
					if gp or capturing or not JH.Running then return end
					if i.KeyCode.Name == (S.LagKey or "L") then setLag(not on) end
				end)
				task.spawn(function()
					while JH.Running do
						if on and tick() - since > (S.LagMax or 6) then setLag(false) end
						task.wait(0.2)
					end
					pcall(function() NC:SetOutgoingKBPSLimit(0) end)
				end)
			end
		end

		do
			local ut2 = JH.menuNew("Unlock All", "U")
			local uc = card(ut2, "Unlock everything", true)
			local function unlockAll()
				local PD, cfg
				for _, m in ipairs(getloadedmodules()) do
					local ok, tb = pcall(require, m)
					if ok and type(tb) == "table" then
						if not PD and type(rawget(tb, "ProfileData")) == "table" then PD = tb end
						if not cfg and type(rawget(tb, "Accessories")) == "table" and type(rawget(tb, "GreenEffects")) == "table" then cfg = tb end
					end
				end
				if not PD or not cfg then return 0 end
				local inv = PD.ProfileData.Inventory
				if type(inv) ~= "table" then return 0 end
				local added = 0
				local function dict(cat, names)
					inv[cat] = inv[cat] or {}
					for _, n in ipairs(names) do
						if inv[cat][n] == nil then inv[cat][n] = { 255, 255, 255 } added = added + 1 end
					end
				end
				local function arr(cat, names)
					inv[cat] = inv[cat] or {}
					for _, n in ipairs(names) do
						if not table.find(inv[cat], n) then table.insert(inv[cat], n) added = added + 1 end
					end
				end
				local function keys(tb)
					local o = {}
					if type(tb) ~= "table" then return o end
					for k, v in pairs(tb) do
						if type(k) == "string" then o[#o + 1] = k
						elseif type(v) == "table" and type(v.Name) == "string" then o[#o + 1] = v.Name
						elseif type(v) == "string" then o[#o + 1] = v end
					end
					return o
				end
				for cat, list in pairs(cfg.Accessories) do
					if cat ~= "SkinTone" and cat ~= "Stores" and type(list) == "table" then dict(cat, keys(list)) end
				end
				arr("Banners", keys(cfg.Banners))
				arr("Titles", keys(cfg.Titles))
				arr("GreenEffects", keys(cfg.GreenEffects.Effects))
				local RS = game:GetService("ReplicatedStorage")
				local function kids(inst) local o = {} if inst then for _, c in ipairs(inst:GetChildren()) do o[#o + 1] = c.Name end end return o end
				pcall(function() dict("Mascots", kids(RS.Accessories.Mascots)) end)
				pcall(function() dict("Vehicles", kids(RS.Assets.Models.Vehicles)) end)
				pcall(function() dict("Basketballs", kids(RS.Assets.Models.Basketball)) end)
				return added
			end
			JH.unlockAll = unlockAll
			-- make the unlocked items actually wearable (visual, on your own screen): when the server refuses to equip something you do not own,
			-- apply it to your character through the game's own appearance code instead
			local function hookEquip()
				local inv
				for _, m in ipairs(getloadedmodules()) do
					local nm = m:GetFullName()
					if string.sub(nm, -17) == "TabMenu.Inventory" then inv = m end
				end
				if not inv then return false end
				local ok, mod = pcall(require, inv)
				if not ok or type(mod) ~= "table" then return false end
				local svc = mod.Services and mod.Services.InventoryService
				if not svc or svc.JHubHooked then return svc and true or false end
				local orig = svc.EquipItem
				if type(orig) ~= "function" then return false end
				svc.JHubHooked = true
				svc.EquipItem = function(self2, cat, name, extra)
					local r1, r2 = orig(self2, cat, name, extra)
					if r1 then return r1, r2 end
					local okc, app = pcall(function() return mod.Controllers.Characters:GetFromString(game:GetService("Players").LocalPlayer.Name).Appearance end)
					if not okc or not app then return r1, r2 end
					local white = { 255, 255, 255 }
					local changes
					if cat == "Mascots" then
						pcall(function() app.appearanceData.Mascot = name app:ApplyMascot(name) end)
						return { Mascot = name }
					elseif cat == "Shoes" then
						changes = { Shoes = { RightShoe = { name, white }, LeftShoe = { name, white } } }
					elseif cat == "Shirt" or cat == "Pants" or cat == "Jersey" then
						changes = {}
						changes[cat] = name
					elseif cat == "Banners" or cat == "Titles" or cat == "GreenEffects" or cat == "Vehicles" or cat == "Basketballs" then
						return r1, r2
					else
						changes = {}
						changes[cat] = { { name, white } }
					end
					local oku = pcall(function() app:UpdateAppearance(changes) end)
					if oku then return changes end
					return r1, r2
				end
				return true
			end
			task.spawn(function()
				while JH.Running do
					if S.UnlockKeep or JH.unlockedOnce then pcall(hookEquip) end
					task.wait(3)
				end
			end)
			JH.hookEquip = hookEquip
			UI.Button(uc, "Unlock everything now", function()
				local n = unlockAll()
				JH.unlockedOnce = true pcall(hookEquip)
				notify("Unlock All", n > 0 and (n .. " items unlocked. Reopen the Tab Menu to see them.") or "Everything already unlocked, or the game's data was not found.", 4)
			end, true)
			tog(uc, "Keep everything unlocked", "UnlockKeep", nil, false)
			note(uc, "Visual only: unlocks every hat, hair, facial hair, shirt, pants, shoes, glasses, chain, backpack, mascot, banner, title, green effect, vehicle and ball in your menus. The game's server can still refuse to equip something you don't really own.")
			task.spawn(function()
				while JH.Running do
					if S.UnlockKeep then pcall(unlockAll) end
					task.wait(4)
				end
			end)
		end

		-- FALLING EFFECTS on the menu (stars, hearts, lightning, clouds and more)
		do
			if S.FxType == nil then S.FxType = "None" end
			if S.FxColor == nil then S.FxColor = "Ice" end
			if S.FxSpeed == nil then S.FxSpeed = 1 end
			if S.FxAmount == nil then S.FxAmount = 20 end
			local RS2 = game:GetService("RunService")
			local host = Main
			local layer = Instance.new("Frame")
			layer.Name = "JHubFx" layer.BackgroundTransparency = 1 layer.Size = UDim2.fromScale(1, 1) layer.ZIndex = 30 layer.ClipsDescendants = true layer.Active = false
			Instance.new("UICorner", layer).CornerRadius = UDim.new(0, 14)
			layer.Parent = host
			local flash = Instance.new("Frame")
			flash.BackgroundColor3 = Color3.fromRGB(220, 235, 255) flash.BackgroundTransparency = 1 flash.BorderSizePixel = 0 flash.Size = UDim2.fromScale(1, 1) flash.ZIndex = 31 flash.Parent = layer
			local GLYPHS = {
				Stars = { "★", "☆", "★" }, Hearts = { "♥" }, Clouds = { "☁" }, Snow = { "●", "•" }, Rain = { "|" }, Sparkles = { "★", "✚" },
				Bubbles = { "◎", "○" }, Petals = { "✿" }, Notes = { "♫" }, Bolts = { "⚡" }, Diamonds = { "◈", "❖" }, Lightning = {},
				Mix = { "★", "♥", "☁", "★", "✿", "♫", "◎", "⚡" },
			}
			local COLORS = { Ice = Color3.fromRGB(120, 190, 255), White = Color3.fromRGB(240, 248, 255), Pink = Color3.fromRGB(255, 140, 190), Gold = Color3.fromRGB(255, 214, 90), Mint = Color3.fromRGB(110, 240, 190), Violet = Color3.fromRGB(180, 140, 255), Red = Color3.fromRGB(255, 90, 90), Orange = Color3.fromRGB(255, 160, 70), Yellow = Color3.fromRGB(255, 240, 90), Green = Color3.fromRGB(110, 255, 110), Cyan = Color3.fromRGB(80, 240, 240), Blue = Color3.fromRGB(80, 130, 255), Purple = Color3.fromRGB(190, 100, 255) }
			local parts, lastType = {}, nil
			local nextBolt = 0
			local function clear() for _, p in ipairs(parts) do p.l:Destroy() end parts = {} end
			local function spawnOne(first)
				local list = GLYPHS[S.FxType]
				if not list or #list == 0 then return end
				local l = Instance.new("TextLabel")
				l.BackgroundTransparency = 1 l.Font = Enum.Font.GothamBold l.Text = list[math.random(#list)] l.ZIndex = 30
				l.TextColor3 = (S.FxColor == "Rainbow" and Color3.fromHSV(math.random(), 0.6, 1) or COLORS[S.FxColor] or COLORS.Ice)
				local cloud = S.FxType == "Clouds"
				local size = cloud and math.random(26, 44) or math.random(12, 24)
				l.TextSize = size l.Size = UDim2.fromOffset(size + 4, size + 4)
				l.TextTransparency = 0.15 + math.random() * 0.35
				l.Parent = layer
				local W, H = layer.AbsoluteSize.X, layer.AbsoluteSize.Y
				local p = { l = l, x = math.random() * W, y = first and math.random() * H or -size, vy = (cloud and 8 or 40) + math.random() * (cloud and 8 or 60), sw = math.random() * 2 * math.pi, sa = 10 + math.random() * 20, vx = cloud and (10 + math.random() * 15) or 0 }
				if cloud then p.y = math.random() * H p.x = -size end
				parts[#parts + 1] = p
			end
			local acc = 0
			RS2.RenderStepped:Connect(function(dt)
				if not JH.Running then return end
				if not Window.Visible or S.FxType == "None" then
					if #parts > 0 then clear() end
					flash.BackgroundTransparency = 1
					return
				end
				if lastType ~= S.FxType then clear() lastType = S.FxType end
				local speed = S.FxSpeed or 1
				local W, H = layer.AbsoluteSize.X, layer.AbsoluteSize.Y
				if S.FxType == "Lightning" or S.FxType == "Mix" then
					if tick() > nextBolt then
						nextBolt = tick() + (2 + math.random() * 3) / math.max(speed, 0.2)
						flash.BackgroundTransparency = 0.75
						local b = Instance.new("TextLabel")
						b.BackgroundTransparency = 1 b.Text = "⚡" b.Font = Enum.Font.GothamBold b.TextSize = math.random(60, 110) b.ZIndex = 32
						b.TextColor3 = (S.FxColor == "Rainbow" and Color3.fromHSV(math.random(), 0.6, 1) or COLORS[S.FxColor] or COLORS.Ice) b.Position = UDim2.fromOffset(math.random() * math.max(W - 100, 10), math.random() * math.max(H * 0.4, 10))
						b.Size = UDim2.fromOffset(100, 110) b.Parent = layer
						task.delay(0.18, function() b:Destroy() end)
					end
					if flash.BackgroundTransparency < 1 then flash.BackgroundTransparency = math.min(1, flash.BackgroundTransparency + dt * 3.5) end
				end
				local want = (S.FxType == "Lightning") and 0 or math.floor(S.FxAmount or 20)
				acc = acc + dt
				while #parts < want and acc > 0.04 do acc = acc - 0.04 spawnOne(#parts < want / 2) end
				for i = #parts, 1, -1 do
					local p = parts[i]
					p.sw = p.sw + dt * 2
					p.y = p.y + p.vy * speed * dt
					p.x = p.x + (p.vx * speed + math.sin(p.sw) * p.sa * 0.3) * dt
					p.l.Position = UDim2.fromOffset(p.x, p.y)
					if p.y > H + 20 or p.x > W + 40 or #parts > want then
						p.l:Destroy() table.remove(parts, i)
					end
				end
			end)
			local ufx = ut
			if ufx then
				local fc = card(ufx, "Falling effects")
				drop(fc, "Effect", "FxType", { "None", "Stars", "Hearts", "Lightning", "Clouds", "Snow", "Rain", "Sparkles", "Bubbles", "Petals", "Notes", "Bolts", "Diamonds", "Mix" }, nil, "None")
				drop(fc, "Color", "FxColor", { "Ice", "Red", "Orange", "Yellow", "Green", "Mint", "Cyan", "Blue", "Violet", "Purple", "Pink", "Gold", "White", "Rainbow" }, nil, "Ice")
				sld(fc, "Speed", "FxSpeed", 0.2, 3, 0.1, 1, "x", nil, 1)
				sld(fc, "Amount", "FxAmount", 5, 60, 1, 0, nil, nil, 20)
				note(fc, "Pick what falls on your menu. Lightning flashes and strikes; clouds drift across.")
			end
		end
		if ut then
			local sk = card(ut, "Skin")
			sld(sk, "Menu see-through", "SkinTrans", 0, 0.9, 0.02, 2, nil, function(v) Main.BackgroundTransparency = S.SkinTrans end, 0.28)
			drop(sk, "Accent (applies next load)", "SkinAccent", { "Ice", "Cyan", "Violet", "Mint", "Red" }, nil, "Ice")
		end
	end

	-- ===== v2.54: chat, live shot feed and announcements back on the Main tab =====
	do
		local mainPage
		for _, p in ipairs(UI.pages) do if p.name == "Main" then mainPage = p end end
		if mainPage then
			local HttpService = game:GetService("HttpService")
			local URL = "https://jayhubv1-default-rtdb.firebaseio.com"
			local http = request or http_request or (syn and syn.request) or (http and http.request)
			local myName = LP.Name
			local function post(path, tbl)
				if not http then return end
				pcall(function() http({ Url = URL .. "/" .. path .. ".json", Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode(tbl) }) end)
			end
			local function get(path, q)
				if not http then return nil, false end
				local ok, res = pcall(function() return http({ Url = URL .. "/" .. path .. ".json" .. (q or ""), Method = "GET" }) end)
				if ok and res and res.Body and (res.StatusCode or 200) == 200 then
					local o, d = pcall(function() return HttpService:JSONDecode(res.Body) end)
					if o then return d, true end
				end
				return nil, false
			end
			local function mkList(cardObj, h)
				local f = Instance.new("ScrollingFrame")
				f.Size = UDim2.new(1, 0, 0, h) f.BackgroundColor3 = Color3.fromRGB(3, 8, 24) f.BackgroundTransparency = 0.3
				f.BorderSizePixel = 0 f.ScrollBarThickness = 3 f.CanvasSize = UDim2.new() f.AutomaticCanvasSize = Enum.AutomaticSize.Y
				f.LayoutOrder = 50 f.Parent = cardObj.frame
				Instance.new("UICorner", f).CornerRadius = UDim.new(0, 8)
				local l = Instance.new("UIListLayout") l.Padding = UDim.new(0, 2) l.SortOrder = Enum.SortOrder.LayoutOrder l.Parent = f
				return f
			end
			local function addLine(f, text, i, col)
				local lb = Instance.new("TextLabel")
				lb.BackgroundTransparency = 1 lb.Size = UDim2.new(1, -8, 0, 0) lb.AutomaticSize = Enum.AutomaticSize.Y
				lb.TextWrapped = true lb.TextXAlignment = Enum.TextXAlignment.Left lb.Font = Enum.Font.GothamMedium lb.TextSize = 12
				lb.TextColor3 = col or Color3.fromRGB(235, 245, 255) lb.Text = text lb.LayoutOrder = i lb.Parent = f
			end
			-- remove the old chat / feed cards so only these new ones remain
			for _, f in ipairs(mainPage.frame:GetChildren()) do
				if f:IsA("Frame") then
					for _, d in ipairs(f:GetDescendants()) do
						if d:IsA("TextLabel") and (d.Text == "JHub Chat (everyone on this script)" or d.Text == "Live feed (everyone's shots)") then f:Destroy() break end
					end
				end
			end
			local chat = UI.Card(mainPage, "JHub Chat (everyone on this script)")
			local chatList = mkList(chat, 150)
			local msg = ""
			local box = UI.Input(chat, "Message", { get = function() return msg end, set = function(v) msg = tostring(v or "") end }, nil, "say something to everyone")
			local function send()
				local m = (box and box.Text ~= "" and box.Text) or msg
				if m == "" then return end
				msg = ""
				if box then box.Text = "" end
				task.spawn(post, "chat", { name = myName, text = string.sub(m, 1, 200), t = os.time() })
				addLine(chatList, myName .. ": " .. m, 99999)
			end
			UI.Button(chat, "Send", send, true)
			do
				for _, ch in ipairs(chat.frame:GetChildren()) do
					if ch:IsA("GuiObject") and ch ~= chatList then
						local head = ch:IsA("TextLabel") and ch.Text == "JHub Chat (everyone on this script)"
						for _, d in ipairs(ch:GetDescendants()) do
							if d:IsA("TextLabel") and d.Text == "JHub Chat (everyone on this script)" then head = true break end
						end
						if not head and ch.LayoutOrder < 50 and ch.LayoutOrder > 0 then ch.LayoutOrder = ch.LayoutOrder + 100 end
					end
				end
			end
			if box then box.FocusLost:Connect(function(enter) if enter then send() end end) end
			local feed = UI.Card(mainPage, "Live feed (everyone's shots)")
			local feedList = mkList(feed, 130)
			local fcount = 0
			JH.feedPost = function(text)
				task.spawn(function()
					local ty = string.match(text, "Shot Type%s*([^%]]-)%s*%]") or "?"
					ty = string.gsub(ty, "^[%-%s]+", "")
					local pc = string.match(text, "Percentage%s*%-?%s*([%d%.]+)")
					local v0 = Shot.classifyFB and Shot.classifyFB(text)
					local word = v0 and tostring(v0) or nil
					if not word then
						task.wait(0.5)
						local ok, last = pcall(function() return JH.OK.autoGreen.Stats.Last end)
						if ok and last and tostring(last) ~= "" then word = string.lower(tostring(last)) end
					end
					if not word and pc then
						local p = tonumber(pc) or 0
						word = (p >= 99 and "green") or (p >= 90 and "good") or "off"
					end
					local verdict = (word or "shot") .. (pc and (" " .. pc .. "%") or "")
					fcount = fcount + 1
					addLine(feedList, string.format("%s | %s | %s", myName, ty, verdict), 90000 + fcount, Color3.fromRGB(120, 200, 255))
					post("feed", { name = myName, shot = ty, verdict = verdict, t = os.time() })
				end)
			end
			local status = Instance.new("TextLabel")
			status.BackgroundTransparency = 1 status.Size = UDim2.new(1, 0, 0, 16) status.Font = Enum.Font.GothamMedium status.TextSize = 11
			status.TextXAlignment = Enum.TextXAlignment.Left status.TextColor3 = Color3.fromRGB(120, 165, 225) status.Text = "connecting..." status.LayoutOrder = 400 status.Parent = chat.frame
			local Q = '?orderBy="$key"&limitToLast=30'
			local sigChat, sigFeed = "", ""
			local lastKey
			local fails = 0
			local function render(list, data, fmt, keep)
				for _, ch in ipairs(list:GetChildren()) do if ch:IsA("TextLabel") and ch.LayoutOrder < 90000 then ch:Destroy() end end
				local keys = {}
				for k in pairs(data) do keys[#keys + 1] = k end
				table.sort(keys)
				for i, k in ipairs(keys) do
					local m = data[k]
					if type(m) == "table" then addLine(list, fmt(m), i, keep) end
				end
				return keys
			end
			local function visible() return Window.Visible and UI.current and UI.current.name == "Main" end
			local dirty = { chat = nil, feed = nil }
			local function showChat(data)
				local keys = render(chatList, data, function(m) return tostring(m.name or "?") .. ": " .. tostring(m.text or "") end)
				chatList.CanvasPosition = Vector2.new(0, 99999)
				return keys
			end
			local function showFeed(data)
				render(feedList, data, function(m) return string.format("%s | %s | %s", tostring(m.name or "?"), tostring(m.shot or "?"), tostring(m.verdict or "?")) end, Color3.fromRGB(150, 190, 235))
			end
			task.spawn(function()
				while JH.Running do
					if not http then status.Text = "your executor can't make web requests, chat and feed are off" task.wait(10)
					else
						local cd, ok1 = get("chat", Q)
						local fd, ok2 = get("feed", Q)
						if ok1 or ok2 then
							fails = 0
							status.Text = "connected"
						else
							fails = fails + 1
							status.Text = "reconnecting..."
						end
						if type(cd) == "table" then
							local ks = {}
							for k in pairs(cd) do ks[#ks + 1] = k end
							table.sort(ks)
							local sig = #ks .. (ks[#ks] or "")
							if sig ~= sigChat then
								sigChat = sig
								local newest = cd[ks[#ks]]
								if lastKey and type(newest) == "table" and newest.name ~= myName then notify("JHub Chat", tostring(newest.name) .. ": " .. tostring(newest.text), 4) end
								lastKey = ks[#ks]
								dirty.chat = cd
							end
						end
						if type(fd) == "table" then
							local ks = {}
							for k in pairs(fd) do ks[#ks + 1] = k end
							table.sort(ks)
							local sig = #ks .. (ks[#ks] or "")
							if sig ~= sigFeed then sigFeed = sig dirty.feed = fd end
						end
						if visible() then
							if dirty.chat then showChat(dirty.chat) dirty.chat = nil end
							if dirty.feed then showFeed(dirty.feed) dirty.feed = nil end
						end
						task.wait(fails > 3 and 8 or 2.5)
					end
				end
			end)
			-- show anything that came in while another tab was open the moment Main is opened
			task.spawn(function()
				while JH.Running do
					if visible() then
						if dirty.chat then showChat(dirty.chat) dirty.chat = nil end
						if dirty.feed then showFeed(dirty.feed) dirty.feed = nil end
					end
					task.wait(0.5)
				end
			end)
		end
	end

	-- clean up stray announcement screens left behind by earlier loads of the script
	do
		pcall(function()
			local parent = (gethui and gethui()) or game:GetService("CoreGui")
			local found = {}
			for _, p in ipairs({ parent, game:GetService("CoreGui"):FindFirstChild("RobloxGui") }) do
				if p then for _, g in ipairs(p:GetChildren()) do if g.Name == "JHubAnnouncement" then found[#found + 1] = g end end end
			end
			for i = 1, #found - 1 do found[i]:Destroy() end
		end)
	end

	-- ===== v2.55: 2.0.19 logo in light blue, Practical Basketball title, logo fonts, menu color + rainbow =====
	do
		if S.MenuColor == nil then S.MenuColor = "Ice" end
		if S.LogoFont == nil or not S.LogoFontV2 then S.LogoFont = "PermanentMarker" S.LogoFontV2 = true end
		local CL = { Ice = Color3.fromRGB(120, 190, 255), Red = Color3.fromRGB(255, 80, 80), Orange = Color3.fromRGB(255, 160, 70), Yellow = Color3.fromRGB(255, 235, 90), Green = Color3.fromRGB(100, 240, 110), Mint = Color3.fromRGB(100, 240, 190), Cyan = Color3.fromRGB(70, 235, 235), Blue = Color3.fromRGB(70, 120, 255), Violet = Color3.fromRGB(170, 120, 255), Purple = Color3.fromRGB(200, 90, 255), Pink = Color3.fromRGB(255, 130, 190), Gold = Color3.fromRGB(255, 210, 80), White = Color3.fromRGB(240, 248, 255) }
		local NAMES = { "Ice", "Red", "Orange", "Yellow", "Green", "Mint", "Cyan", "Blue", "Violet", "Purple", "Pink", "Gold", "White", "Rainbow" }
		local FONTS = { "Creepster", "Bangers", "PermanentMarker", "Fantasy", "SciFi", "Arcade", "Oswald", "GothamBlack", "GothamBold", "Cartoon" }
		local function curColor()
			if S.MenuColor == "Rainbow" then return Color3.fromHSV((os.clock() * 0.15) % 1, 0.55, 1) end
			return CL[S.MenuColor] or CL.Ice
		end
		local logos = {}
		local function reg(root) logos[#logos + 1] = root end
		-- clone of the original header logo (J, H, JHub V1 + bars) for the sidebar
		local badge = Header:FindFirstChild("LogoBadge")
		local sideLogo
		if badge then
			sideLogo = badge:Clone()
			sideLogo.Name = "JHubSideLogo" sideLogo.Visible = true sideLogo.ZIndex = 6
			sideLogo.AnchorPoint = Vector2.new(0.5, 0) sideLogo.Position = UDim2.new(0.5, 0, 0, 14)
			local sc = Instance.new("UIScale") sc.Scale = 1.35 sc.Parent = sideLogo
			sideLogo.Parent = nil
			badge.Visible = false
		end
		local body = UI.LogoBody
		if body then
			for _, d in ipairs(body:GetChildren()) do
				if d.Name == "JHubBack" or d.Name == "JHubText" then d:Destroy() elseif d:IsA("GuiObject") then d.Visible = true end
			end
			reg(body)
		end
		if sideLogo then reg(sideLogo) end
		for _, d in ipairs(Header:GetChildren()) do
			if d:IsA("TextLabel") then d.Visible = false end
		end
		local function tint(c)
			local dark = c:Lerp(Color3.new(0, 0, 0), 0.45)
			for _, root in ipairs(logos) do
				if root == sideLogo then root.BackgroundColor3 = Color3.fromRGB(6, 8, 14) root.BackgroundTransparency = 0 end
				for _, d in ipairs(root:GetDescendants()) do
					if d:IsA("UIGradient") then
						local pp = d.Parent
						if pp == root or (pp:IsA("Frame") and root == sideLogo and (pp.Size.X.Scale >= 0.9 or pp.Size.X.Offset >= 60 or pp.Size.X.Scale >= 2)) then d.Color = ColorSequence.new(c:Lerp(Color3.new(0, 0, 0), 0.8), Color3.new(0, 0, 0))
						elseif d.Parent:IsA("TextLabel") then d.Color = ColorSequence.new(c, c:Lerp(Color3.new(1, 1, 1), 0.25))
						else d.Color = ColorSequence.new(c, dark) end
					elseif d:IsA("UIStroke") then d.Color = c
					elseif d:IsA("TextLabel") then
						if d:FindFirstChildOfClass("UIGradient") then d.TextColor3 = Color3.new(1, 1, 1) else d.TextColor3 = c end
					elseif d:IsA("Frame") and not d:FindFirstChildOfClass("UIGradient") and d.BackgroundTransparency < 0.9 then d.BackgroundColor3 = c end
				end
			end
		end
		local function setFont(root)
			local f = Enum.Font[S.LogoFont] or Enum.Font.Creepster
			for _, d in ipairs(root:GetDescendants()) do
				if d:IsA("TextLabel") and (d.Text == "J" or d.Text == "H" or d.Text == "JHub V1") then d.Font = f end
			end
		end
		local pb
		local function layout()
			local rail
			for _, d in ipairs(Main:GetDescendants()) do
				if d.Name == "JHubRailPanel" then rail = d end
			end
			if rail then
				rail.BackgroundColor3 = Color3.new(0, 0, 0) rail.BackgroundTransparency = 0.04
				local old = rail.Parent:FindFirstChild("JHubRailLogo") if old then old.Visible = false end
				if sideLogo and sideLogo.Parent ~= rail.Parent then sideLogo.Parent = rail.Parent end
				if sideLogo then sideLogo.Position = UDim2.new(0.1125, 0, 0, 16) end
			end
			pb = pb or Main:FindFirstChild("PBTag")
			if pb then
				pb.Text = "Practical Basketball" pb.TextScaled = false pb.TextSize = 26
				pb.Size = UDim2.fromOffset(420, 30) pb.Position = UDim2.new(0.5, 0, 0, 4)
				pb.Font = Enum.Font[S.LogoFont] or Enum.Font.Creepster
				pb.TextStrokeColor3 = Color3.new(0, 0, 0) pb.TextStrokeTransparency = 0.5
			end
			for _, r in ipairs(logos) do setFont(r) end
		end
		local function colorAll()
			local c = curColor()
			tint(c)
			pb = pb or Main:FindFirstChild("PBTag")
			if pb then pb.TextColor3 = c end
			if not JH.MenuRainbow then
				for _, d in ipairs(Main:GetChildren()) do
					if d:IsA("UIStroke") then d.Color = c end
				end
			else
				for _, d in ipairs(Main:GetChildren()) do if d:IsA("UIStroke") then d.Color = c end end
			end
			Theme.Outline = c Theme.AccentA = c Theme.AccentB = c
			local ib = Header:FindFirstChild("JHubIconBar")
			local gl = Main:FindFirstChild("RedGlow") if gl then gl.BackgroundColor3 = c:Lerp(Color3.new(0, 0, 0), 0.55) end
		end
		local function rings()
			local c = curColor()
			for _, d in ipairs(Main:GetDescendants()) do
				if d:IsA("UIStroke") and d.Parent ~= Main then
					local h, sa, v = d.Color:ToHSV()
					if sa > 0.4 and v > 0.3 then d.Color = c end
				end
			end
		end
		JH.menuColorFn = curColor
		JH.menuRecolor = function() pcall(layout) pcall(colorAll) end
		pcall(layout) pcall(colorAll)
		Window.AnchorPoint = Vector2.new(0.5, 0.5) Window.Position = UDim2.fromScale(0.5, 0.5)
		task.spawn(function()
			local n = 0
			while JH.Running do
				n = n + 1
				if Window.Visible or (UI.LogoRoot and UI.LogoRoot.Visible) then
					if S.MenuColor == "Rainbow" or n % 10 == 0 then pcall(colorAll) end
					if n % 10 == 0 then pcall(layout) end
					if n % 10 == 5 then pcall(rings) end
				end
				task.wait(0.1)
			end
		end)
		local ut
		for _, x in ipairs(JH.menuTabs) do if x.name == "UI Customizations" then ut = x end end
		if ut then
			local lc = JH.menuCard(ut, "Menu color and logo")
			JH.menuDrop(lc, "Menu color", "MenuColor", NAMES, function() pcall(colorAll) end, "Ice")
			JH.menuDrop(lc, "Logo font", "LogoFont", FONTS, function() pcall(layout) end, "PermanentMarker")
			JH.menuNote(lc, "Menu color changes the logos, title, border and glow. Rainbow cycles through every color.")
		end
	end

	-- ===== v2.56: J-Hub character logo (outline) on the sidebar and the open button =====
	do
		local B64 = [=====[]=====]
		local function dec(d)
			local f = (crypt and crypt.base64decode) or (crypt and crypt.base64 and crypt.base64.decode) or base64_decode or (base64 and base64.decode)
			if f then local ok, r = pcall(f, d) if ok and type(r) == "string" and #r > 100 then return r end end
			local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
			d = d:gsub("[^" .. chars .. "=]", "")
			return (d:gsub(".", function(x)
				if x == "=" then return "" end
				local r, f2 = "", (chars:find(x, 1, true) - 1)
				for i = 6, 1, -1 do r = r .. (f2 % 2 ^ i - f2 % 2 ^ (i - 1) > 0 and "1" or "0") end
				return r
			end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
				if #x ~= 8 then return "" end
				local c = 0
				for i = 1, 8 do c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0) end
				return string.char(c)
			end))
		end
		local asset
		pcall(function()
			writefile("JHubV1_logo.png", dec(B64))
			asset = (getcustomasset or getsynasset)("JHubV1_logo.png")
		end)
		if asset then
			local function mk(parent, name)
				local im = parent:FindFirstChild(name)
				if im then return im end
				im = Instance.new("ImageLabel")
				im.Name = name im.BackgroundTransparency = 1 im.Image = asset im.ZIndex = 20 im.ScaleType = Enum.ScaleType.Fit
				im.Parent = parent
				return im
			end
			local body = UI.LogoBody
			local function tintC() return JH.menuColorFn and JH.menuColorFn() or Color3.fromRGB(120, 190, 255) end
			local bi
			if body then
				for _, d in ipairs(body:GetChildren()) do if d:IsA("GuiObject") then d.Visible = false end end
				body.BackgroundColor3 = Color3.new(0, 0, 0) body.BackgroundTransparency = 0
				bi = mk(body, "JHubArtImg") bi.Size = UDim2.fromScale(1, 1)
			end
			local si
			local function step()
				local panel
				for _, d in ipairs(Main:GetDescendants()) do if d.Name == "JHubRailPanel" then panel = d break end end
				if panel then
					local old = panel.Parent:FindFirstChild("JHubSideLogo") if old then old.Visible = false end
					si = mk(panel.Parent, "JHubSideImg")
					si.Size = UDim2.fromOffset(112, 112) si.AnchorPoint = Vector2.new(0.5, 0) si.Position = UDim2.new(0.1125, 0, 0, 6)
				end
				local c = tintC()
				if si then si.ImageColor3 = c end
				if bi then
					local rr = UDim.new(S.BtnRound or 0.5, 0)
					for _, o in ipairs({ body, bi, UI.LogoRoot and UI.LogoRoot:FindFirstChild("Frame") }) do
						if o then
							local uc = o:FindFirstChildOfClass("UICorner")
							if not uc then uc = Instance.new("UICorner") uc.Parent = o end
							uc.CornerRadius = rr
						end
					end
					for _, d in ipairs(UI.LogoRoot:GetDescendants()) do

						if d:IsA("Frame") and d.Parent == UI.LogoRoot and d ~= body then d.BackgroundColor3 = c d.BackgroundTransparency = 1 - (S.BtnGlow or 0.35) * 0.5 end
					end
					local rs = body:FindFirstChild("JHubRing")
					if not rs then rs = Instance.new("UIStroke") rs.Name = "JHubRing" rs.ApplyStrokeMode = Enum.ApplyStrokeMode.Border rs.Parent = body end
					rs.Color = Color3.new(0, 0, 0) rs.Thickness = S.BtnBorder or 3
					for _, d in ipairs(UI.LogoRoot:GetDescendants()) do
						if d:IsA("UIStroke") then d.Color = Color3.new(0, 0, 0) d.Transparency = 0 end
					end
					for _, d in ipairs(UI.LogoRoot:GetChildren()) do
						if d:IsA("Frame") and d.Name ~= "LogoBody" then d.BackgroundColor3 = Color3.new(0, 0, 0) end
					end
					body.BackgroundColor3 = Color3.new(0, 0, 0)
					bi.ImageColor3 = c
					for _, d in ipairs(body:GetChildren()) do if d:IsA("GuiObject") and d ~= bi and d.Visible then d.Visible = false end end
				end
			end
			task.spawn(function()
				while JH.Running do pcall(step) task.wait(0.1) end
			end)
			if S.BtnRound == nil then S.BtnRound = 0.5 end
			if S.BtnBorder == nil then S.BtnBorder = 3 end
			if S.BtnGlow == nil then S.BtnGlow = 0.35 end
			if S.LogoSize == nil or S.LogoSize < 70 then S.LogoSize = 78 end
			pcall(function() UI.applyLogo() end)
			local ut2
			for _, x in ipairs(JH.menuTabs) do if x.name == "UI Customizations" then ut2 = x end end
			if ut2 then
				local bc = JH.menuCard(ut2, "Open button (logo)")
				JH.menuSld(bc, "Size", "LogoSize", 40, 150, 2, 0, nil, function() pcall(function() UI.applyLogo() end) end, 78)
				JH.menuSld(bc, "Roundness (0.5 = circle)", "BtnRound", 0, 0.5, 0.05, 2, nil, nil, 0.5)
				JH.menuSld(bc, "Border", "BtnBorder", 0, 8, 0.5, 1, nil, nil, 3)
				JH.menuSld(bc, "Glow", "BtnGlow", 0, 1, 0.05, 2, nil, nil, 0.35)
				JH.menuNote(bc, "Drag the button anywhere. Roundness 0.5 makes it a full circle.")
			end
		end
	end
	do return end
	local main = find("Main")
	if main then pcall(UI.select, main) end
end

end -- JHubMain

local ok, err = xpcall(JHubMain, function(e) return tostring(e) .. "\n" .. debug.traceback() end)
if not ok then
	warn("[JHub] failed to load: " .. tostring(err))
	pcall(function()
		local sg = Instance.new("ScreenGui")
		sg.Name = "JHubError"
		sg.ResetOnSpawn = false
		local okP = pcall(function() sg.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
		if not okP or not sg.Parent then sg.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui") end
		local box = Instance.new("TextButton")
		box.Size = UDim2.fromOffset(440, 230)
		box.Position = UDim2.new(0.5, -220, 0.5, -115)
		box.BackgroundColor3 = Color3.fromRGB(10, 30, 70)
		box.TextColor3 = Color3.new(1, 1, 1)
		box.Font = Enum.Font.Code
		box.TextSize = 12
		box.TextWrapped = true
		box.TextXAlignment = Enum.TextXAlignment.Left
		box.TextYAlignment = Enum.TextYAlignment.Top
		box.Text = "JHub failed to load. Screenshot this and send it (tap to close):\n\n" .. tostring(err)
		box.Parent = sg
		box.Activated:Connect(function() sg:Destroy() end)
		if setclipboard then pcall(setclipboard, tostring(err)) end
	end)
end